// Aldune legal knowledge base: a closed universe of California wage-and-hour topics the assistant may answer from.
// Every entry carries citations and a last-verified date. Sources consulted are listed in docs/LEGAL_SOURCES.md.
// This is legal information, not legal advice; entries describe general rules and note open questions.
import { COMPUTER_PRO, INDUSTRY_MIN_WAGE, LOCAL_MIN_WAGE, stateMinWageOn, exemptSalaryFloor } from '../engine/time';

export interface LawTopic { id: string; title: string; summary: string; points: string[]; citations: string[]; keywords: string[]; verified: string; status?: string; engineRule?: string; category?: string; remedies?: string[] }
const V = '2026-10-05';
const money = (n: number) => `$${n.toFixed(2)}`;

export const LAW: LawTopic[] = [
  { id: 'meal-periods', category: 'Breaks', title: 'Meal periods', engineRule: 'CA-MEAL', verified: V,
    summary: 'Non-exempt employees must be provided a 30-minute, duty-free meal period that starts no later than the end of the fifth hour of work, and a second one that starts no later than the end of the tenth hour.',
    points: ['First meal may be waived by mutual consent only if the workday is 6 hours or less.', 'Second meal may be waived only if the workday is 12 hours or less and the first meal was not waived.', 'Employers must relieve employees of all duty and control, but need not police whether they work (Brinker, 2012).', 'Time records showing missed, short, or late meals create a rebuttable presumption of a violation; meal periods may not be rounded (Donohue, 2021).', 'On-duty meal periods are allowed only when the nature of the work prevents relief, by written agreement revocable at any time.', 'Certain construction, commercial driver, security, and electrical/gas utility employees under qualifying collective bargaining agreements are exempt from § 512 (Lab. Code § 512(e)–(g)).'],
    citations: ['Lab. Code § 512', 'IWC Wage Orders § 11', 'Brinker Restaurant Corp. v. Superior Court (2012) 53 Cal.4th 1004', 'Donohue v. AMN Services, LLC (2021) 11 Cal.5th 58'], keywords: ['meal', 'lunch', 'break', 'fifth hour', '5th hour', 'waiver', 'late meal', 'short meal', 'second meal', 'on-duty', 'brinker', 'donohue'] },
  { id: 'meal-premises', category: 'Breaks', title: 'Meal periods spent on premises and other controlled time', verified: V,
    summary: 'Time is compensable “hours worked” when the employee is subject to the employer’s control. A meal period during which the employer prohibits leaving the premises can be compensable even when a CBA exempts the employer from § 512 meal-period rules.',
    points: ['Time spent in employer-required exit security procedures on the employer’s premises is compensable (Huerta, 2024).', 'Time spent on mandatory bag checks is compensable (Frlekin v. Apple, 2020).', 'Travel on employer property can be compensable “employer-mandated travel” only if it starts at the first location where the employee’s presence is required for an employment-related reason.', 'Requiring employees to remain on premises or eat at a designated place makes the meal period compensable; practical difficulty in leaving is not enough by itself.'],
    citations: ['Huerta v. CSI Electrical Contractors (2024) 15 Cal.5th 908', 'Frlekin v. Apple Inc. (2020) 8 Cal.5th 1038', 'IWC Wage Orders § 2 (hours worked)'], keywords: ['premises', 'security', 'bag check', 'gate', 'controlled', 'hours worked', 'huerta', 'frlekin', 'stay on site', 'travel'] },
  { id: 'rest-periods', category: 'Breaks', title: 'Rest periods', engineRule: 'CA-REST', verified: V,
    summary: 'Non-exempt employees must be authorized and permitted to take a paid 10-minute rest period for every 4 hours worked or major fraction, in the middle of each work period where practicable.',
    points: ['No rest period is required for a workday under 3½ hours.', '3½–6 hours: 1; over 6 to 10 hours: 2; over 10 to 14 hours: 3.', 'Employees must be relieved of all duties and may not be required to remain on call (Augustus, 2016).', 'Rest periods cannot be waived; there is no rest-period waiver equivalent to the meal-period waiver.', 'Employers are not required to record rest periods, so evidence often comes from policies, attestations, and testimony.'],
    citations: ['IWC Wage Orders § 12', 'Lab. Code § 226.7', 'Augustus v. ABM Security Services, Inc. (2016) 2 Cal.5th 257'], keywords: ['rest', 'rest break', 'ten minute', '10 minute', 'paid break', 'on call', 'augustus', 'waive rest'] },
  { id: 'premiums', category: 'Breaks', title: 'Meal and rest premium pay', verified: V,
    summary: 'For each workday a compliant meal or rest period is not provided, the employer owes one additional hour of pay at the employee’s regular rate of compensation — up to one meal premium and one rest premium per day.',
    points: ['“Regular rate of compensation” includes nondiscretionary pay such as shift differentials and production bonuses, not just the base hourly rate (Ferra, 2021).', 'Premiums are wages: unpaid premiums support wage-statement and waiting-time claims (Naranjo, 2022).', 'Claims for premiums carry a three-year limitations period (Murphy v. Kenneth Cole, 2007), four years under Bus. & Prof. Code § 17200.'],
    citations: ['Lab. Code § 226.7(c)', 'Ferra v. Loews Hollywood Hotel, LLC (2021) 11 Cal.5th 858', 'Naranjo v. Spectrum Security Services, Inc. (2022) 13 Cal.5th 93', 'Murphy v. Kenneth Cole Productions, Inc. (2007) 40 Cal.4th 1094'], keywords: ['premium', 'one hour', 'penalty pay', 'ferra', 'naranjo', 'regular rate of compensation', 'missed break pay'] },
  { id: 'overtime', category: 'Hours and pay', title: 'Overtime and double time', engineRule: 'CA-OT-RECON', verified: V,
    summary: 'Non-exempt employees earn 1.5× the regular rate for hours over 8 in a workday, over 40 in a workweek, and the first 8 hours on the seventh consecutive day of work in a workweek; 2× for hours over 12 in a day and over 8 on the seventh consecutive day.',
    points: ['Daily and weekly overtime are not double-counted: hours already paid as daily overtime don’t also count toward the 40-hour weekly threshold.', 'Alternative workweek schedules adopted by secret-ballot election can change daily thresholds (Lab. Code § 511).', 'Unapproved overtime that was worked must still be paid; discipline, not nonpayment, is the remedy.'],
    citations: ['Lab. Code § 510', 'Lab. Code § 511', 'Lab. Code § 1194'], keywords: ['overtime', 'ot', 'double time', 'dt', 'seventh day', '7th day', '40 hours', '8 hours', '12 hours', 'workweek', 'alternative workweek'] },
  { id: 'ag-overtime', category: 'Hours and pay', title: 'Agricultural overtime (AB 1066)', verified: V,
    summary: 'Since January 1, 2025, all agricultural employers pay overtime after 8 hours in a day or 40 in a week and double time after 12 hours in a day. Larger employers (26+) reached that standard in 2022; employers with 25 or fewer phased in from 2022 to 2025.',
    points: ['Phase-in for 26+ employees: 2019 9.5/55, 2020 9/50, 2021 8.5/45, 2022 onward 8/40 with double time after 12.', 'Employers with 25 or fewer followed the same steps three years later (2022–2025).', 'Agricultural workers are entitled to 1.5× for the first 8 hours on the seventh consecutive workday and 2× after 8 hours that day.', 'Wage Order 14 governs agricultural occupations.'],
    citations: ['Lab. Code §§ 857–864 (AB 1066, Phase-In Overtime for Agricultural Workers Act of 2016)', 'IWC Wage Order 14'], keywords: ['agriculture', 'agricultural', 'farm', 'farmworker', 'ab 1066', 'wage order 14', 'harvest', 'grower', 'phase-in'] },
  { id: 'regular-rate', category: 'Hours and pay', title: 'Regular rate of pay', engineRule: 'CA-REGRATE', verified: V,
    summary: 'Overtime must be paid at a multiple of the regular rate, which includes hourly pay plus nondiscretionary bonuses, commissions, shift differentials, and piece-rate earnings.',
    points: ['Flat-sum bonuses earned in one pay period: divide by nonovertime hours actually worked and use a 1.5 multiplier (Alvarado); bonuses that rise with each hour worked (production bonuses, commissions) may be divided by total hours. Alvarado applies retroactively.', 'Flat-sum bonuses (e.g., attendance bonuses) are divided by nonovertime hours only and multiplied by 1.5 for overtime hours (Alvarado, 2018).', 'Discretionary bonuses, gifts, and expense reimbursements are excluded.', 'The same regular rate of compensation drives meal and rest premiums (Ferra).'],
    citations: ['Lab. Code § 510', 'Alvarado v. Dart Container Corp. of California (2018) 4 Cal.5th 542', 'DLSE Enforcement Policies and Interpretations Manual § 49'], keywords: ['regular rate', 'bonus', 'shift differential', 'commission', 'alvarado', 'flat sum', 'nondiscretionary'] },
  { id: 'minimum-wage', category: 'Minimum wage', title: 'California minimum wage (state)', engineRule: 'CA-MINWAGE', verified: V,
    summary: `The statewide minimum wage is ${money(stateMinWageOn('2026-01-01'))} per hour for all employers as of January 1, 2026 (${money(stateMinWageOn('2025-01-01'))} in 2025). Higher local or industry rates control where they apply.`,
    points: ['Employees can recover unpaid minimum wages plus an equal amount of liquidated damages, unless the employer shows good faith and reasonable grounds (Lab. Code § 1194.2).', 'Learners may be paid 85% of minimum wage for their first 160 hours in occupations where they have no similar experience.', 'There is no tip credit in California.'],
    citations: ['Lab. Code §§ 1182.12, 1194, 1194.2, 1197', 'DIR Minimum Wage Order MW-2026'], keywords: ['minimum wage', 'min wage', '16.90', 'state minimum', 'liquidated', 'tip credit', 'learner'] },
  { id: 'local-minimum-wage', category: 'Minimum wage', title: 'Local minimum wage ordinances', verified: V,
    summary: `About 40 California cities and counties set rates above the state minimum. Aldune applies these effective-dated rates when an employee’s work location matches: ${Object.entries(LOCAL_MIN_WAGE).slice(0, 12).map(([c, s]) => `${c.replace(/\b\w/g, m => m.toUpperCase())} ${money(s[s.length - 1].rate)} (from ${s[s.length - 1].effective})`).join('; ')}; and others.`,
    points: ['Many localities adjust on January 1; Los Angeles, San Francisco, Berkeley, Santa Monica, Pasadena, Fremont, and Milpitas adjust on July 1.', 'Some cities have size tiers (e.g., Hayward, Novato, Sonoma); Aldune applies the large-employer rate unless the employee file gives a local rate.', 'Local rates do not change the exempt salary floor, which is tied to the state minimum wage.', 'Earlier local rates not in Aldune’s table can be supplied per employee in the census (local_min_wage).'],
    citations: ['Municipal minimum wage ordinances (see UC Berkeley Labor Center inventory)', 'Lab. Code § 1205 (local authority)'], keywords: ['local minimum', 'city minimum', 'los angeles', 'san francisco', 'san jose', 'san diego', 'oakland', 'berkeley', 'mountain view', 'west hollywood', 'ordinance', 'county'] },
  { id: 'industry-minimum-wage', category: 'Minimum wage', title: 'Fast food and health care minimum wages', verified: V,
    summary: `Fast food workers covered by AB 1228 earn at least $20.00 per hour since April 1, 2024. Covered health care workers earn tiered rates under SB 525: ${Object.values(INDUSTRY_MIN_WAGE).filter(x => x.label.startsWith('Health')).map(x => `${x.label.replace(' (SB 525)', '')}: ${x.schedule.map(s => `${money(s.rate)} from ${s.effective}`).join(', ')}`).join('; ')}.`,
    points: ['Fast food coverage: limited-service restaurants in national chains of more than 60 establishments, with carve-outs (inside grocery stores; certain bakeries; airports, hotels, event centers, theme parks, museums, gambling establishments, certain corporate campuses, public-land concessions). Council increases are capped at the lesser of 3.5% or CPI-W; none after 2029 (§§ 1474, 1475).', 'Health care: covers all employees of covered facilities providing patient care or supporting services (including janitorial, food service, clerical, security) and certain contracted staff; exempt health care employees must earn the greater of 150% of the health care minimum or 200% of the state minimum. Effective dates were conditioned by the § 1182.16 funding trigger — verify the operative schedule.', 'Fast food applies to national chains with 60+ establishments (Lab. Code § 1474 et seq.).', 'SB 525 rates depend on facility type and size, not job title; rural and safety-net hospitals have separate schedules.', 'Exempt fast food and health care employees have higher salary floors tied to these rates.'],
    citations: ['Lab. Code §§ 1182.14, 1182.16, 1475', 'Lab. Code § 1474 et seq. (AB 1228)', 'Lab. Code § 1182.14 et seq. (SB 525)'], keywords: ['fast food', 'ab 1228', 'health care', 'healthcare', 'hospital', 'sb 525', 'clinic', 'dialysis', '$20', '$25'] },
  { id: 'exemptions', category: 'Classification', title: 'Exempt classification (executive, administrative, professional)', engineRule: 'CA-CLASS', verified: V,
    summary: `White-collar exemptions require a monthly salary of at least twice the state minimum wage for full-time work — ${money(exemptSalaryFloor('2026-01-01'))} a year in 2026 — and that the employee be primarily engaged (more than half the time) in exempt duties.`,
    points: ['Both the salary test and the duties test must be met; job titles don’t control.', `Computer software professionals: at least ${money(COMPUTER_PRO[COMPUTER_PRO.length - 1].hourly)}/hour or ${money(COMPUTER_PRO[COMPUTER_PRO.length - 1].annual)}/year in 2026 (${money(COMPUTER_PRO[0].hourly)}/hour, ${money(COMPUTER_PRO[0].annual)}/year in 2025).`, 'Misclassified employees are owed overtime, meal and rest premiums, and accurate wage statements.'],
    citations: ['Lab. Code § 515', 'Lab. Code § 515.5 (computer professionals)', 'IWC Wage Orders § 1'], keywords: ['exempt', 'salary', 'salaried', 'misclassified', 'manager', 'supervisor', 'duties test', '70,304', 'computer professional', 'software'] },
  { id: 'contractors', category: 'Classification', title: 'Independent contractors (ABC test)', engineRule: 'CA-CLASS', verified: V,
    summary: 'A worker is an employee unless the hiring entity proves all three ABC prongs: (A) free from control and direction, (B) work outside the usual course of the hiring entity’s business, and (C) customarily engaged in an independently established trade or business.',
    points: ['Codified by AB 5 after Dynamex (2018); statutory exemptions (business-to-business, certain professional services) use the Borello test instead.', 'Willful misclassification carries civil penalties of $5,000–$15,000 per violation, or $10,000–$25,000 for a pattern or practice.'],
    citations: ['Lab. Code §§ 2775–2787', 'Lab. Code § 226.8', 'Dynamex Operations West, Inc. v. Superior Court (2018) 4 Cal.5th 903'], keywords: ['contractor', '1099', 'abc test', 'ab 5', 'ab5', 'dynamex', 'borello', 'misclassification', 'gig'] },
  { id: 'wage-statements', category: 'Pay records and notices', title: 'Wage statements (pay stubs)', engineRule: 'CA-WS-226', verified: V,
    summary: 'Each pay stub must show gross wages, total hours (non-exempt), piece-rate units and rates, all deductions, net wages, pay period dates, the employee’s name and last four of SSN or an ID, the employer’s legal name and address, and every hourly rate with hours at each; paid sick leave available must appear on the stub or a separate writing.',
    points: ['Knowing and intentional violations causing injury: $50 for the first pay period and $100 for each later one, capped at $4,000 per employee; one-year limitations period.', 'Underpaid wages or premiums make the stated gross and hours inaccurate (Naranjo).', 'Employers must keep wage statement records for at least three years.'],
    citations: ['Lab. Code § 226(a), (e)', 'Lab. Code § 246(i)', 'Naranjo v. Spectrum Security Services, Inc. (2022) 13 Cal.5th 93'], keywords: ['wage statement', 'pay stub', 'paystub', '226', 'itemized', 'sick leave balance', 'deductions'] },
  { id: 'final-pay', category: 'Separation', title: 'Final pay and waiting-time penalties', engineRule: 'CA-FINALPAY', verified: V,
    summary: 'Final wages are due immediately on discharge, within 72 hours after a quit without notice, and on the last day if the employee gave at least 72 hours’ notice. Willful failure triggers up to 30 days of the employee’s daily wages.',
    points: ['A good-faith dispute over whether wages are owed defeats willfulness.', 'Waiting-time claims carry a three-year limitations period (Pineda, 2010).', 'Unpaid premiums at separation can support waiting-time penalties (Naranjo).'],
    citations: ['Lab. Code §§ 201, 202, 203', 'Pineda v. Bank of America, N.A. (2010) 50 Cal.4th 1389'], keywords: ['final pay', 'final paycheck', 'termination', 'quit', 'waiting time', '203', 'discharge', 'separation', '72 hours'] },
  { id: 'pay-timing', category: 'Hours and pay', title: 'Paydays during employment', engineRule: 'CA-PAYTIMING', verified: V,
    summary: 'Wages earned between the 1st and 15th must be paid by the 26th, and wages earned from the 16th to month-end by the 10th of the next month; weekly or biweekly payroll must be paid within 7 calendar days after the period closes.',
    points: ['Paydays must be posted (Lab. Code § 207).', 'Penalty: $100 for an initial violation and $200 plus 25% of the amount withheld for subsequent or willful violations (Lab. Code § 210).'],
    citations: ['Lab. Code §§ 204, 207, 210'], keywords: ['payday', 'pay timing', 'late paycheck', '204', '210', 'semimonthly', 'biweekly'] },
  { id: 'expenses', category: 'Hours and pay', title: 'Business expense reimbursement', engineRule: 'CA-EXPENSE', verified: V,
    summary: 'Employers must reimburse all necessary expenditures employees incur in direct consequence of their duties, including mileage and a reasonable percentage of personal cell phone use even on unlimited plans.',
    points: ['Interest accrues from the date of the expense; prevailing employees recover attorney’s fees.', 'Cochran v. Schwan’s (2014) held phone reimbursement is required even when the employee’s plan cost does not increase.'],
    citations: ['Lab. Code § 2802', 'Cochran v. Schwan’s Home Service, Inc. (2014) 228 Cal.App.4th 1137'], keywords: ['expense', 'reimbursement', 'mileage', 'cell phone', 'phone', '2802', 'cochran', 'tools', 'uniform'] },
  { id: 'rounding', category: 'Hours and pay', title: 'Time rounding', engineRule: 'CA-TIMEKEEP', verified: V, status: 'Open question: Camp v. Home Depot (S277518) — review granted February 1, 2023; briefing closed in late 2023; no opinion had issued as of mid-2026. Until the Court rules, rounding of shift punches carries risk wherever time is captured to the minute',
    summary: 'California courts have allowed facially neutral rounding that does not undercompensate employees over time (See’s Candy, 2012), but meal periods may not be rounded (Donohue, 2021), and a Court of Appeal held that employers who can capture exact time must pay for all of it (Camp, 2022).',
    points: ['Camp limits itself: it does not decide whether rounding is lawful where the employer cannot capture actual minutes (See’s Candy’s net-neutrality test still applies there), nor whether an employer able to capture minutes must do so. Because review was granted, Camp is citable under Cal. Rules of Court, rule 8.1115(e).', 'Aldune’s method: where actual minutes are captured, any net downward rounding loss per employee is flagged (Camp); where only rounded data exists, the See’s Candy net-neutrality test is applied over the full period.', 'While review is pending, Camp may be cited for persuasive value and to establish a conflict in authority.', 'Lowest-risk practice: pay to the minute.'],
    citations: ['Camp v. Home Depot U.S.A., Inc. (2022) 84 Cal.App.5th 638 (review granted, S277518)', 'Cal. Rules of Court, rule 8.1115(e)', 'See’s Candy Shops, Inc. v. Superior Court (2012) 210 Cal.App.4th 889', 'Donohue v. AMN Services, LLC (2021) 11 Cal.5th 58', 'Camp v. Home Depot U.S.A., Inc. (2022) 84 Cal.App.5th 638, review granted (S277518)'], keywords: ['rounding', 'round', 'quarter hour', 'see\'s candy', 'camp', 'home depot', 'punch rounding'] },
  { id: 'split-reporting', category: 'Hours and pay', title: 'Split shifts and reporting-time pay', verified: V, status: 'Split shifts are tested automatically from punches (rule CA-SPLIT); reporting-time pay needs scheduled-shift data.', engineRule: 'CA-SPLIT',
    summary: 'When an employee works a split shift (non-consecutive hours with an unpaid, non-meal break), one extra hour at minimum wage is owed unless total pay already exceeds minimum wage for all hours plus one. Employees who report as scheduled but are sent home early are owed half the scheduled shift (2–4 hours) at their regular rate.',
    points: ['Reporting time: when an employee reports but gets less than half the scheduled day, pay half the scheduled hours — at least 2 and no more than 4 hours — at the regular rate (never below minimum wage); a second same-day report with under 2 hours of work earns 2 hours. Exceptions: threats to persons or property, civil-authority recommendations, utility failures, acts of God, and paid-standby employees called in off schedule.', 'Split shift: one hour at the minimum wage in addition to minimum wage for that day, reduced by any amount the employee earned that day above minimum wage (DLSE method); not owed where the employee lives at the workplace.', 'Split-shift premium: IWC Wage Orders § 4(C); an interruption of more than one hour that is not a bona fide meal period. The premium is offset by pay above minimum wage (Aleman v. AirTouch Cellular, 2012).', 'Reporting-time pay: IWC Wage Orders § 5; on-call scheduling may trigger it (Ward v. Tilly’s, 2019).'],
    citations: ['IWC Wage Orders §§ 4(C), 5', 'Aleman v. AirTouch Cellular (2012) 209 Cal.App.4th 556', 'Ward v. Tilly’s, Inc. (2019) 31 Cal.App.5th 1167'], keywords: ['split shift', 'reporting time', 'sent home', 'on call', 'call-in', 'tilly'] },
  { id: 'sick-leave', category: 'Pay records and notices', title: 'Paid sick leave', verified: V,
    summary: 'Employees earn at least 1 hour of paid sick leave per 30 hours worked (or a front-loaded grant), may use at least 40 hours or 5 days per year, and accrual may be capped at no less than 80 hours or 10 days (SB 616, effective 2024).',
    points: ['Available balance must appear on the wage statement or a separate writing on payday.', 'Retaliation for using sick leave is prohibited.'],
    citations: ['Lab. Code §§ 245–249 (as amended by SB 616)', 'Lab. Code § 246(i)'], keywords: ['sick leave', 'paid sick', 'psl', 'sb 616', 'accrual', 'sick days'] },
  { id: 'paga-overview', category: 'PAGA and enforcement', title: 'PAGA overview', verified: V,
    summary: 'The Private Attorneys General Act lets an aggrieved employee recover civil penalties for Labor Code violations on behalf of the State and other aggrieved employees, after giving notice to the LWDA and the employer.',
    points: ['One-year limitations period from the notice, plus tolling during the LWDA notice period.', 'Under the 2024 amendments, the plaintiff must personally have suffered each violation alleged within the period.', 'Wholesale waivers of representative PAGA claims are unenforceable (Iskanian, 2014); individual PAGA claims can be compelled to arbitration (Viking River, 2022); the plaintiff keeps standing for non-individual claims (Adolph v. Uber, 2023); courts may not dismiss PAGA claims as unmanageable (Estrada, 2024).'],
    citations: ['Lab. Code §§ 2698–2699.8', 'Iskanian v. CLS Transportation (2014) 59 Cal.4th 348', 'Viking River Cruises, Inc. v. Moriana (2022) 596 U.S. 639', 'Adolph v. Uber Technologies, Inc. (2023) 14 Cal.5th 1104', 'Estrada v. Royalty Carpet Mills, Inc. (2024) 15 Cal.5th 582'], keywords: ['paga', 'private attorneys general', 'lwda', 'notice', 'representative', 'aggrieved', 'iskanian', 'viking river', 'adolph', 'estrada', 'standing'] },
  { id: 'paga-2024', category: 'PAGA and enforcement', title: 'PAGA 2024 amendments (AB 2288, SB 92)', verified: V,
    summary: 'For notices filed on or after June 19, 2024: default penalty $100 per aggrieved employee per pay period; penalties capped at 15% if the employer took all reasonable steps before the notice and 30% if within 60 days after; employees receive 35% of penalties (up from 25%).',
    points: ['Wage-statement violations where the employee could promptly and easily determine the information: $25 per employee per pay period.', 'Isolated, nonrecurring violations lasting no more than 30 days or four consecutive pay periods: $50 cap.', '$200 per pay period only if a court or agency found the policy unlawful within the prior five years, or the conduct was malicious, fraudulent, or oppressive.', 'Penalties are cut in half for employers who pay weekly.', 'Reasonable steps can include periodic payroll audits and acting on the results, lawful written policies, supervisor training, and corrective action with supervisors.', 'Cure: employers with fewer than 100 employees can submit a cure proposal to the LWDA within 33 days; larger employers can request an early evaluation conference. Cures for wage violations generally require paying wages owed plus 7% interest.', 'Notices filed before June 19, 2024 follow the prior statute: $100 initial and $200 subsequent penalties, 75/25 split, no reasonable-steps caps.'],
    citations: ['Lab. Code § 2699 (as amended by AB 2288, 2024)', 'Lab. Code § 2699.3 (as amended by SB 92, 2024)'], keywords: ['paga reform', 'ab 2288', 'sb 92', '2024', 'reasonable steps', '15%', '30%', 'cure', 'early evaluation', 'weekly', '$25', '$50', '$200', '35%'] },
  { id: 'limitations', category: 'PAGA and enforcement', title: 'Statutes of limitations', verified: V,
    summary: 'Unpaid wages, overtime, and meal/rest premiums: 3 years (4 years as restitution under Bus. & Prof. Code § 17200). Wage-statement penalties: 1 year. Waiting-time penalties: 3 years. PAGA: 1 year.',
    points: ['Three years: liabilities created by statute other than a penalty (Code Civ. Proc. § 338(a)); one year: statutory penalties such as § 226(e) and PAGA (§ 340(a)); four years: UCL restitution of unpaid wages (Bus. & Prof. Code §§ 17203, 17208) — restitution only, not penalties.', 'Waiting-time penalties: § 203(b) ties the period to the underlying wage claim (three years) — Pineda v. Bank of America (2010) 50 Cal.4th 1389.', 'Equal Pay Act: three years, reaching back up to six.', 'Penalties are not recoverable as restitution under § 17200.', 'Prejudgment interest on unpaid wages accrues at 10% simple.'],
    citations: ['Bus. & Prof. Code § 17203', 'Pineda v. Bank of America, N.A. (2010) 50 Cal.4th 1389', 'Code Civ. Proc. §§ 338, 340', 'Bus. & Prof. Code § 17208', 'Lab. Code § 218.6; Civ. Code § 3289'], keywords: ['statute of limitations', 'lookback', 'how far back', 'three years', 'four years', '17200', 'interest'] },
  { id: 'arbitration', category: 'Agreements and settlements', title: 'Arbitration agreements', verified: V,
    summary: 'Class-action waivers in employment arbitration agreements are generally enforceable (Epic Systems, 2018), but agreements must meet Armendariz minimums and cannot waive representative PAGA claims.',
    points: ['A wholesale waiver of representative PAGA standing in every forum is unenforceable (Iskanian, as preserved by Viking River). A severability clause lets the employer arbitrate the individual PAGA claim, but a non-severable “poison pill” barring all representative claims voids the whole agreement (DeMarinis).', 'The FAA preempts AB 51 (Lab. Code § 432.6), so requiring arbitration as a condition of employment is not itself unlawful (Chamber of Commerce v. Bonta).', 'Armendariz minimums: neutral arbitrator, adequate discovery, written award, all statutory remedies, and the employer pays all costs unique to arbitration; shortened limitation periods and one-sided terms support unconscionability.', 'Armendariz: neutral arbitrator, adequate discovery, written award, all statutory remedies, employer pays costs unique to arbitration.', 'Employees may elect court for sexual harassment or assault disputes (EFAA, 2022).', 'Employers that miss arbitration fee deadlines can lose the right to arbitrate (Code Civ. Proc. §§ 1281.97–1281.98).'],
    citations: ['DeMarinis v. Heritage Bank of Commerce (2023) 98 Cal.App.5th 776', 'Chamber of Commerce of the U.S. v. Bonta (9th Cir. 2023) 62 F.4th 473', 'Epic Systems Corp. v. Lewis (2018) 584 U.S. 497', 'Armendariz v. Foundation Health Psychcare Services (2000) 24 Cal.4th 83', '9 U.S.C. §§ 401–402 (EFAA)', 'Code Civ. Proc. §§ 1281.97–1281.98'], keywords: ['arbitration', 'class waiver', 'armendariz', 'efaa', 'epic systems', 'arbitrate'] },
  { id: 'settlements', category: 'Agreements and settlements', title: 'Settling wage claims with employees', verified: V,
    summary: 'Wages concededly due must be paid without requiring a release (Lab. Code § 206.5). Individual settlements of disputed claims with putative class members are permitted if not misleading or coercive (Chindarah v. Pick Up Stix, 2009), but individuals cannot release the State’s representative PAGA claims.',
    points: ['Separation and settlement agreements that restrict disclosure must include the Gov. Code § 12964.5 statement.', 'Courts can limit or set aside communications with putative class members that are misleading or coercive (Gulf Oil v. Bernard).'],
    citations: ['Lab. Code §§ 206, 206.5', 'Chindarah v. Pick Up Stix, Inc. (2009) 171 Cal.App.4th 796', 'Gov. Code § 12964.5', 'Gulf Oil Co. v. Bernard (1981) 452 U.S. 89'], keywords: ['settle', 'settlement', 'release', 'pick up stix', 'chindarah', '206.5', 'individual settlement', 'back pay'] },

  { id: 'paga-cure', title: 'PAGA cure and early evaluation procedures', verified: V, category: 'PAGA and enforcement',
    summary: 'For notices filed on or after October 1, 2024, employers with fewer than 100 employees during the notice period may submit a confidential cure proposal to the LWDA within 33 days of receiving the notice; the LWDA may set a conference within 14 days, and the cure must be completed within 45 days of the conference with a sworn notice of completion.',
    points: ['A wage cure requires paying unpaid wages for three years before the notice, 7% interest, any statutory liquidated damages, and reasonable attorney’s fees and costs, plus coming into compliance.', 'Wage-statement violations can be cured by all employers within 33 days by providing compliant wage statements for each affected pay period in the prior three years (or written notice of the correct employer name/address where that was the only defect).', 'Completion requires a sworn notification to the employee and LWDA; where money is paid, the LWDA expects a payroll audit and check register.', 'Employers with 100 or more employees may, on being served with a PAGA complaint, request a stay and an early evaluation conference, stating which violations they will cure and which they dispute.', 'A sufficient cure bars PAGA penalties for the cured violations, subject to statutory exceptions.'],
    citations: ['Lab. Code § 2699.3 (as amended by SB 92, 2024)', 'Lab. Code § 2699(d)–(e) (as amended by AB 2288, 2024)'], keywords: ['cure', 'to cure', 'cure a', 'curing', 'cure proposal', 'early evaluation', 'eec', '33 days', '45 days', '7%', 'lwda conference', 'sworn notification', 'cure plan'], remedies: ['paga_cure', 'back_pay'] },
  { id: 'records-requests', title: 'Employee requests for payroll and personnel records', verified: V, category: 'Pay records and notices',
    summary: 'Current and former employees may inspect or copy wage-statement records within 21 calendar days of a request (Lab. Code § 226(b)–(c)) and personnel files within 30 days (§ 1198.5); they are entitled to copies of instruments they signed relating to employment (§ 432).',
    points: ['Failure to comply with a § 226 records request: $750 penalty (§ 226(f)); with a § 1198.5 request: $750 penalty (§ 1198.5(k)).', 'Employers must keep payroll records at least three years (§§ 226(a), 1174(d)) and personnel records at least three years after termination (§ 1198.5(c)).', 'Willful failure to maintain required records: civil penalty under § 1174.5.', 'Records requests are often the first step before a PAGA notice or wage claim.'],
    citations: ['Lab. Code § 226(b), (c), (f)', 'Lab. Code § 1198.5', 'Lab. Code § 432', 'Lab. Code §§ 1174, 1174.5'], keywords: ['records request', 'personnel file', 'payroll records', '1198.5', '226(c)', '432', 'copy of records', 'inspect', 'recordkeeping', '1174'], remedies: ['recordkeeping'] },
  { id: 'wage-notice', title: 'Wage Theft Prevention Act notice (§ 2810.5)', verified: V, category: 'Pay records and notices',
    summary: 'At hire, non-exempt employees must receive a written notice of their pay rate(s) and basis, overtime rate, allowances, regular payday, the employer’s legal name, DBA, address and phone, workers’ compensation carrier, paid sick leave rights, and other information; changes must be noticed within seven days unless shown on the next wage statement.',
    points: ['Applies to non-exempt employees (with limited exceptions such as certain public and CBA-covered employees).', 'Missing or outdated notices are a frequent PAGA allegation.', 'Use the Labor Commissioner’s template notice.'],
    citations: ['Lab. Code § 2810.5'], keywords: ['2810.5', 'wage theft prevention', 'notice to employee', 'pay rate notice', 'new hire notice'], remedies: ['notices'] },
  { id: 'know-your-rights-2026', title: 'Workplace Know Your Rights Act notice (SB 294, 2026)', verified: V, category: 'Recent changes',
    summary: 'Starting in 2026, employers must give every employee a standalone written notice of workplace rights — first by February 1, 2026, then annually and at hire — using the Labor Commissioner’s template where possible, and must offer employees the chance to designate an emergency contact.',
    points: ['Notice covers workers’ compensation, immigration-related protections, concerted-activity rights, and constitutional rights when interacting with law enforcement at work.', 'Provide it in the language normally used for work communications.', 'Keep compliance records for three years, including the date each notice was provided.', 'Penalties: up to $500 per employee per violation; emergency-contact notification failures up to $500 per day, capped at $10,000 per employee.'],
    citations: ['Lab. Code §§ 1550–1559 (SB 294, 2025)'], keywords: ['sb 294', 'know your rights', 'annual notice', 'emergency contact', '1550', 'immigration notice'], remedies: ['notices'] },
  { id: 'pay-transparency', title: 'Pay scales and equal pay (SB 642, 2026)', verified: V, category: 'Recent changes',
    summary: 'Employers with 15 or more employees must include a pay scale in job postings and give current employees the pay scale for their position on request. From 2026, a “pay scale” is a good-faith estimate of the range the employer reasonably expects to pay upon hire.',
    points: ['SB 642 extends the Equal Pay Act’s reach (pay differences between employees of “another sex”) and allows recovery of up to six years of back wages.', 'For Equal Pay Act purposes, “wages” include salary, bonuses, stock, benefits, and other compensation.'],
    citations: ['Lab. Code § 432.3', 'Lab. Code § 1197.5 (as amended by SB 642, 2025)'], keywords: ['pay transparency', 'pay scale', 'job posting', 'equal pay', 'sb 642', '432.3', '1197.5', 'pay equity'] },
  { id: 'deductions', title: 'Wage deductions and kickbacks', verified: V, category: 'Hours and pay',
    summary: 'Employers may not take back wages paid or make deductions except as required by law, authorized in writing for insurance, benefits, or similar purposes, or permitted for specific items; deductions for cash shortages, breakage, or equipment loss are barred unless caused by a dishonest or willful act or gross negligence.',
    points: ['Deductions for cash shortages, breakage, or lost equipment are barred unless caused by a dishonest or willful act or gross negligence (Wage Orders § 8; Kerr’s Catering).', 'Unlawful withholding under §§ 212, 216, 221, 222, or 223 carries a penalty of $100 per employee (initial) and $200 plus 25% of the amount withheld (subsequent or willful) (§ 225.5).', 'Unlawful deductions and kickbacks: Lab. Code §§ 221, 223, 224.', 'Final-pay deductions for unreturned property require care; don’t withhold final wages to offset.', 'Wage Order § 8 limits cash shortage and breakage deductions.'],
    citations: ['Lab. Code § 225.5', 'Kerr’s Catering Service v. Department of Industrial Relations (1962) 57 Cal.2d 319', 'Lab. Code §§ 221, 223, 224', 'IWC Wage Orders § 8'], keywords: ['deduction', 'deductions', 'kickback', 'shortage', 'breakage', 'withhold', '221', '224'] },
  { id: 'tips', title: 'Tips and gratuities', verified: V, category: 'Hours and pay',
    summary: 'Gratuities belong to the employees for whom they were left. Employers, managers, and supervisors may not take any part of tips, and credit-card tips must be paid no later than the next regular payday.',
    points: ['Mandatory tip pools among employees who provide service are permitted; owners and agents may not participate.', 'No tip credit against the minimum wage in California.'],
    citations: ['Lab. Code §§ 350–356', 'Lab. Code § 351'], keywords: ['tips', 'tip', 'gratuity', 'tip pool', '351', 'service charge'] },
  { id: 'vacation', title: 'Vacation and PTO payout', verified: V, category: 'Separation',
    summary: 'Earned vacation and PTO is wages that vests as it is earned; it cannot be forfeited and must be paid at separation at the final rate (Suastez). Reasonable accrual caps are allowed; “use it or lose it” policies are not.',
    points: ['Unpaid vested vacation at separation supports waiting-time penalties.', 'Paid sick leave (distinct from PTO) need not be paid out unless combined into a PTO policy.'],
    citations: ['Lab. Code § 227.3', 'Suastez v. Plastic Dress-Up Co. (1982) 31 Cal.3d 774'], keywords: ['vacation', 'pto', 'paid time off', 'payout', 'use it or lose it', 'accrual cap', '227.3', 'suastez'], remedies: ['final_pay'] },
  { id: 'commissions', title: 'Commission agreements', verified: V, category: 'Hours and pay',
    summary: 'Commission plans must be in writing, state how commissions are computed and paid, and be signed with a copy given to the employee. Commissions are part of the regular rate for overtime.',
    points: ['Non-exempt commissioned employees still need overtime at a regular rate that includes commissions.', 'Inside sales employees may be exempt only under the commissioned-employee exemption of certain Wage Orders (more than 1.5× minimum wage and more than half of pay from commissions).'],
    citations: ['Lab. Code § 2751', 'IWC Wage Orders 4 and 7, § 3(D)'], keywords: ['commission', 'commissions', '2751', 'sales plan', 'inside sales'] },
  { id: 'day-of-rest', title: 'Day of rest and alternative workweeks', verified: V, category: 'Hours and pay',
    summary: 'Employees are entitled to one day’s rest in seven (Lab. Code §§ 551–552), which applies per workweek and may be waived voluntarily (Mendoza v. Nordstrom, 2017). Alternative workweek schedules adopted by secret-ballot election can allow up to 10-hour days without daily overtime.',
    points: ['Seventh-consecutive-day premium pay under § 510 is separate from the day-of-rest rule.', 'Make-up time requests (§ 513) let employees make up personal time in the same workweek without overtime, within limits.'],
    citations: ['Lab. Code §§ 511, 513, 551, 552', 'Mendoza v. Nordstrom, Inc. (2017) 2 Cal.5th 1074'], keywords: ['day of rest', 'seven days', 'alternative workweek', '4/10', 'make up time', '551', '552', '511', '513'] },
  { id: 'hours-worked', title: 'What counts as hours worked (travel, on-call, sleep, preparation)', verified: V, category: 'Hours and pay',
    summary: 'Hours worked include all time the employee is subject to the employer’s control, and all time suffered or permitted to work, whether or not required. Compulsory travel on employer transport, required on-call restrictions, and pre- and post-shift tasks are commonly compensable.',
    points: ['Required employer-provided transportation time is compensable (Morillion, 2000).', 'On-call and sleep time in 24-hour shifts can be compensable under Wage Order 4 (Mendiola, 2015).', 'De minimis rule does not apply to regularly occurring small amounts of off-the-clock work under California law (Troester, 2018).', 'Security checks and controlled meal periods: see Huerta (2024).'],
    citations: ['IWC Wage Orders § 2(K)', 'Morillion v. Royal Packing Co. (2000) 22 Cal.4th 575', 'Mendiola v. CPS Security Solutions (2015) 60 Cal.4th 833', 'Troester v. Starbucks Corp. (2018) 5 Cal.5th 829'], keywords: ['hours worked', 'off the clock', 'off-the-clock', 'travel time', 'on call', 'sleep time', 'de minimis', 'troester', 'morillion', 'mendiola', 'pre-shift', 'donning'], remedies: ['reconciliation', 'timekeeping'] },
  { id: 'uniforms-tools', title: 'Uniforms and tools', verified: V, category: 'Hours and pay',
    summary: 'When uniforms are required, the employer must provide and maintain them; tools and equipment necessary to perform the job must be provided, except hand tools customarily required of employees earning at least twice the minimum wage.',
    points: ['Required items the employee buys are reimbursable under § 2802.'],
    citations: ['IWC Wage Orders § 9', 'Lab. Code § 2802'], keywords: ['uniform', 'tools', 'equipment', 'boots', 'safety gear'], remedies: ['expenses'] },
  { id: 'lactation', title: 'Lactation accommodation', verified: V, category: 'Breaks',
    summary: 'Employers must provide reasonable break time and a private, clean lactation space (not a bathroom) close to the work area, and a written lactation policy. Lactation time that does not run concurrently with paid rest periods may be unpaid.',
    points: ['The written policy must state the right to request accommodation, the request process, the employer’s duty to respond, and the right to file a complaint with the Labor Commissioner; include it in the handbook and give it to new hires and employees asking about parental leave (§ 1034).', 'Denial counts as a § 226.7 violation (one hour of pay), and the Labor Commissioner may impose $100 per day of denial (§ 1033). Employers under 50 may claim undue hardship only for the space requirements.', 'Denial of lactation break time is treated like a rest-period violation for premium purposes (Lab. Code § 226.7).', 'Policy must be in the handbook and given at hire and on request.'],
    citations: ['Lab. Code §§ 1030–1034', 'Lab. Code § 226.7'], keywords: ['lactation', 'breastfeeding', 'nursing', '1030', '1034'], remedies: ['policies'] },
  { id: 'retaliation', title: 'Retaliation protections', verified: V, category: 'PAGA and enforcement',
    summary: 'Employers may not retaliate against employees for complaining about unpaid wages, filing claims, or disclosing violations. Adverse action within 90 days of protected activity creates a rebuttable presumption of retaliation (§ 98.6).',
    points: ['Civil penalties up to $10,000 per employee per violation under both § 1102.5 and § 98.6; once protected activity is shown to be a contributing factor, the employer must prove by clear and convincing evidence it would have acted the same anyway (§ 1102.6).', 'Wage releases do not reach § 1102.5 retaliation claims based on a different factual predicate (Amaro).', 'Civil penalty up to $10,000 per employee per violation under § 98.6.', 'Whistleblower protections under § 1102.5; employer must show by clear and convincing evidence it would have acted anyway (Lawson, 2022).', 'Settlements and attestation programs must not discourage complaints.'],
    citations: ['Lab. Code § 1102.6', 'Lab. Code § 98.6', 'Lab. Code § 1102.5', 'Lawson v. PPG Architectural Finishes, Inc. (2022) 12 Cal.5th 703'], keywords: ['retaliation', 'retaliate', 'whistleblower', '98.6', '1102.5', 'lawson', 'fired for complaining'] },
  { id: 'labor-commissioner', title: 'Labor Commissioner wage claims and judgments', verified: V, category: 'PAGA and enforcement',
    summary: 'Employees can file wage claims with the Labor Commissioner (DLSE), leading to a settlement conference and a “Berman” hearing; awards become court judgments if not appealed. Employers appealing must post a bond for the award.',
    points: ['Timeline: within 30 days the Commissioner decides whether to hold a hearing; any hearing is held within 90 days; the Order, Decision, or Award issues within 15 days with interest (§§ 98, 98.1).', 'Appeal to superior court within 10 days for de novo review; the employer must post an undertaking equal to the award, and an unsuccessful appellant pays the other side’s fees — an employee who recovers anything above zero is successful (§ 98.2, amended by SB 261).', 'Appeal to superior court is de novo; an employer who appeals and loses pays the employee’s attorney’s fees (§ 98.2).', 'SB 261 (2025) strengthens enforcement of unpaid Labor Commissioner judgments, including added penalties for employers that fail to pay within 180 days.', 'Citations for wage violations can include civil penalties under §§ 558 and 1197.1.'],
    citations: ['Lab. Code §§ 98, 98.1, 98.2', 'Lab. Code §§ 558, 1197.1', 'SB 261 (2025)'], keywords: ['labor commissioner', 'dlse', 'berman', 'wage claim', 'citation', '558', '1197.1', 'sb 261', 'judgment'] },
  { id: 'fees-interest', title: 'Attorney’s fees, interest, and civil penalties', verified: V, category: 'PAGA and enforcement',
    summary: 'Prevailing employees recover attorney’s fees for unpaid minimum wage and overtime (§ 1194) and in other wage actions (§ 218.5); unpaid wages bear prejudgment interest at 10% (§ 218.6; Civ. Code § 3289).',
    points: ['Fee exposure is one-way for minimum wage and overtime claims (§ 1194 — employees only) and two-way for other wage claims (§ 218.5 — employers recover only on a bad-faith finding). Interest accrues at 10% from each wage’s due date (§ 218.6; Civ. Code § 3289(b)).', 'Meal and rest premium claims under § 226.7 are not fee-shifting under § 218.5 (Kirby, 2012), but are often pled alongside fee-shifting claims.', 'Civil penalties under § 558: $50 initial / $100 subsequent per employee per pay period plus underpaid wages (recoverable through PAGA).'],
    citations: ['Lab. Code §§ 218.5, 218.6, 558, 1194', 'Civ. Code § 3289', 'Kirby v. Immoos Fire Protection, Inc. (2012) 53 Cal.4th 1244'], keywords: ['attorney fees', 'attorneys fees', 'interest', '218.5', '218.6', '1194', 'kirby', '558', 'civil penalty'] },
  { id: 'joint-liability', title: 'Client employer and labor contractor liability', verified: V, category: 'PAGA and enforcement',
    summary: 'A client employer that obtains workers from a labor contractor (such as a staffing agency or farm labor contractor) to perform work within its usual course of business shares civil legal responsibility for the contractor’s wage payments.',
    points: ['Applies to client employers with 25+ workers including those supplied by contractors (exceptions apply).', 'Farm labor contractor arrangements are a common source of shared liability in agriculture.'],
    citations: ['Lab. Code § 2810.3'], keywords: ['staffing agency', 'labor contractor', 'farm labor contractor', 'flc', 'joint employer', 'client employer', '2810.3', 'temp workers'] },
  { id: 'piece-rate', title: 'Piece-rate pay (§ 226.2)', verified: V, category: 'Hours and pay', status: 'Not yet calculated automatically by Aldune; requires piece-rate earnings and hours.',
    summary: 'Piece-rate employees must be paid separately for rest and recovery periods at the higher of the minimum wage or their average hourly rate for the workweek, and at least minimum wage for other nonproductive time; wage statements must show these items.',
    points: ['Average hourly rate = total compensation for the workweek excluding rest/recovery pay and overtime premiums ÷ hours excluding rest and recovery periods.', 'Wage statements must show total hours of compensable rest and recovery periods, the rate, and gross pay for them, and nonproductive time and pay.'],
    citations: ['Lab. Code § 226.2', 'Gonzalez v. Downtown LA Motors (2013) 215 Cal.App.4th 36', 'Bluford v. Safeway Stores (2013) 216 Cal.App.4th 864'], keywords: ['piece rate', 'piece-rate', 'piecework', '226.2', 'nonproductive', 'rest and recovery', 'per bin', 'per box'] },
  { id: 'outside-sales', title: 'Outside salesperson exemption', verified: V, category: 'Classification',
    summary: 'Outside salespersons — employees over 18 who customarily and regularly work more than half their working time away from the employer’s place of business selling or obtaining orders — are exempt from overtime and meal/rest rules under the Wage Orders.',
    points: ['Measured by time actually spent, considering the employer’s realistic expectations (Ramirez v. Yosemite Water, 1999).', 'No salary minimum, but § 2802 reimbursement still applies.'],
    citations: ['Lab. Code § 1171', 'IWC Wage Orders § 1(C)', 'Ramirez v. Yosemite Water Co. (1999) 20 Cal.4th 785'], keywords: ['outside sales', 'outside salesperson', 'sales exemption', 'ramirez', 'yosemite'] },

  { id: 'heat-recovery', title: 'Heat-illness recovery (cool-down) periods', verified: V, category: 'Breaks', status: 'Not yet calculated automatically by Aldune; requires temperature and recovery-period data. Whether a separate premium is owed in addition to a rest-period premium on the same day is unsettled.',
    summary: 'Employers with outdoor workplaces must allow and encourage a preventative cool-down rest in the shade of at least five minutes whenever an employee feels the need (Cal. Code Regs., tit. 8, § 3395). Since 2014, Labor Code § 226.7 treats these “recovery periods” like meal and rest periods: an employer may not require work during one, and must pay one additional hour of pay at the regular rate of compensation for each workday a required recovery period is not provided. Recovery periods are paid time.',
    points: ['Shade must be available when the temperature exceeds 80°F (and on request below that).', 'Agriculture, during high heat (95°F or above): ensure each employee takes a minimum 10-minute net cool-down rest every two hours; the cool-down may run concurrently with a regular rest period if timing aligns, and additional rest is required after 8 hours.', 'The indoor heat standard (§ 3396, effective 2024) provides that a preventative cool-down rest has the same meaning as a “recovery period” under § 226.7.', 'Document heat-illness prevention plans, training, and recovery breaks; attestations that cover recovery periods strengthen the record.'],
    citations: ['Lab. Code § 226.7 (as amended by SB 435, 2013, and SB 1360, 2014)', 'Cal. Code Regs., tit. 8, § 3395 (outdoor heat illness prevention)', 'Cal. Code Regs., tit. 8, § 3396 (indoor heat illness prevention)'], keywords: ['heat', 'heat illness', 'recovery period', 'cool-down', 'cool down', 'shade', '3395', '3396', 'sb 435', 'hot weather', '95 degrees', 'outdoor workers'], remedies: ['attestation'] },
  { id: 'wage-orders', title: 'Which IWC Wage Order applies', verified: V, category: 'Industries',
    summary: 'California’s 17 Industrial Welfare Commission Wage Orders set industry-specific rules on hours, meal and rest periods, and recordkeeping. Coverage is generally determined by the employer’s main line of business, not by an individual job.',
    points: ['1 Manufacturing; 2 Personal Service; 3 Canning, Freezing, and Preserving; 4 Professional, Technical, Clerical, Mechanical; 5 Public Housekeeping (restaurants, hotels, hospitals); 6 Laundry, Linen Supply, Dry Cleaning; 7 Mercantile (retail); 8 Industries Handling Products After Harvest; 9 Transportation; 10 Amusement and Recreation; 11 Broadcasting; 12 Motion Picture; 13 Preparing Agricultural Products for Market on the Farm; 14 Agricultural Occupations; 15 Household Occupations; 16 On-Site Construction, Drilling, Logging, and Mining; 17 Miscellaneous.', 'Employers must post the applicable Wage Order where employees can read it.', 'Aldune applies industry-specific timing, overtime, and wage rules when you choose an industry on the Import page.'],
    citations: ['Cal. Code Regs., tit. 8, §§ 11010–11170', 'Lab. Code §§ 1173, 1182'], keywords: ['wage order', 'which wage order', 'iwc', 'industry rules', 'order 4', 'order 5', 'order 9', 'order 16'] },
  { id: 'healthcare-meal-waiver', title: 'Health care meal-period waivers', verified: V, category: 'Industries', engineRule: 'CA-MEAL',
    summary: 'Health care employees covered by Wage Orders 4 and 5 who work shifts longer than eight hours may voluntarily waive, in writing, one of their two meal periods. The waiver is revocable with one day’s notice.',
    points: ['Codified in Labor Code § 516(b) (2015) after Gerard v. Orange Coast Memorial Medical Center upheld the Wage Order provision.', 'Without a valid written waiver, standard second-meal rules apply.', 'SB 525 health care minimum wages apply separately (Lab. Code § 1182.14 et seq.).'],
    citations: ['Lab. Code § 516(b)', 'IWC Wage Orders 4 and 5, § 11(D)', 'Gerard v. Orange Coast Memorial Medical Center (2018) 6 Cal.5th 443'], keywords: ['health care', 'healthcare', 'hospital', 'nurse', '516', 'meal waiver health', '12-hour shift'] },
  { id: 'cmv-drivers', title: 'Commercial drivers: federal preemption of meal and rest rules', verified: V, category: 'Industries',
    summary: 'California’s meal and rest period rules are preempted for drivers of property-carrying commercial motor vehicles subject to the federal hours-of-service rules (IBT Local 2785 v. FMCSA, 9th Cir. 2021). On June 4, 2026, the Ninth Circuit upheld the FMCSA’s extension of preemption to passenger-carrying commercial drivers.',
    points: ['Drivers who operate only within California and are not subject to federal hours-of-service rules remain covered by California meal and rest rules.', 'Wage Order 9 § 3(L) exempts from California overtime drivers whose hours of service are regulated by the U.S. Department of Transportation or by California’s Vehicle Code regulations.', 'Non-driving staff (dispatchers, warehouse, mechanics) keep all California protections.', 'Driver classification as independent contractors is governed by the ABC test.'],
    citations: ['49 U.S.C. § 31141', 'International Brotherhood of Teamsters, Local 2785 v. FMCSA (9th Cir. 2021) 986 F.3d 841', 'California ex rel. Becerra v. FMCSA (9th Cir. June 4, 2026, No. 20-70706)', 'IWC Wage Order 9, § 3(L)'], keywords: ['truck driver', 'trucking', 'cmv', 'fmcsa', 'preemption', 'hours of service', 'driver meal break', 'bus driver'] },
  { id: 'warehouse-quotas', title: 'Warehouse quotas (AB 701)', verified: V, category: 'Industries',
    summary: 'Employers with 100+ employees at a single warehouse distribution center (or 1,000+ across California) must give each employee a written description of any quota, may not use quotas that prevent meal or rest periods, bathroom use, or compliance with safety laws, and must provide quota and work-speed records on request within 14 days.',
    points: ['Time on meal and rest periods and bathroom breaks cannot count against a quota.', 'Retaliation for requesting quota information or complaining is prohibited, with a rebuttable presumption for adverse action within 90 days.'],
    citations: ['Lab. Code §§ 2100–2112 (AB 701, 2021)'], keywords: ['warehouse', 'quota', 'ab 701', 'distribution center', 'productivity standard'] },
  { id: 'motion-picture', title: 'Motion picture and broadcasting meal rules', verified: V, category: 'Industries',
    summary: 'Under Wage Order 12, motion picture employees may work up to six hours before a 30-minute meal period, and each subsequent meal must be called no later than six hours after the end of the previous one. Employees covered by a qualifying collective bargaining agreement in the motion picture or broadcasting industry follow the agreement’s meal terms.',
    points: ['Hot meals and drinks must be provided for work after midnight (except off-production employees regularly scheduled then).', 'The CBA exception requires the agreement to provide meal periods and a monetary remedy.'],
    citations: ['IWC Wage Order 12, § 11(A)', 'Lab. Code § 512(b), (d)', 'Labor Commissioner (DLSE), Meal Periods FAQ'], keywords: ['motion picture', 'film', 'tv production', 'set', 'wage order 12', 'six hours meal'] },
  { id: 'domestic-workers', title: 'Domestic workers and personal attendants', verified: V, category: 'Industries',
    summary: 'Personal attendants who work in a private household — supervising, feeding, or dressing a child or a person who needs supervision — earn overtime at 1.5× after 9 hours in a day or 45 hours in a week. A worker who spends more than 20% of the time on other household duties is an “other domestic worker” under Wage Order 15’s standard rules.',
    points: ['The Domestic Worker Bill of Rights (Lab. Code §§ 1450–1454) made personal-attendant overtime permanent.', 'Most Wage Order 15 provisions, including meal and rest periods, do not apply to personal attendants.', 'Live-in domestic workers have special hour rules under Wage Order 15.'],
    citations: ['Lab. Code §§ 1450–1454', 'Cal. Code Regs., tit. 8, § 11150 (Wage Order 15)'], keywords: ['domestic worker', 'nanny', 'nanny overtime', 'caregiver overtime', 'caregiver', 'personal attendant', 'household', 'housekeeper', '1454'] },
  { id: 'ambulance-breaks', title: 'Private ambulance employees (Prop. 11)', verified: V, category: 'Industries',
    summary: 'Private emergency ambulance employees may be required to remain reachable during meal and rest periods, which must be paid; an interrupted break must be restarted. Employers must also provide specified training and mental-health resources.',
    points: ['Enacted by Proposition 11 (2018).', 'Missed-break claims depend on whether interrupted breaks were restarted.'],
    citations: ['Lab. Code §§ 880–890'], keywords: ['ambulance', 'emt', 'paramedic', 'prop 11', 'on call break'] },
  { id: 'garment', title: 'Garment Worker Protection Act (SB 62)', verified: V, category: 'Industries',
    summary: 'Since January 1, 2022, garment manufacturing workers may not be paid by the piece and must be paid an hourly wage. Brand guarantors share liability for wage violations of their manufacturers and contractors.',
    points: ['Garment manufacturers must register with the Labor Commissioner.', 'Workers can file claims against manufacturers, contractors, and brand guarantors.'],
    citations: ['Lab. Code §§ 2670–2684 (SB 62, 2021)'], keywords: ['garment', 'sb 62', 'apparel', 'sewing', 'piece rate garment'] },
  { id: 'public-works', title: 'Public works: prevailing wage and certified payroll', verified: V, category: 'Industries',
    summary: 'Workers on public works projects must be paid the prevailing wage determined by the Director of Industrial Relations. Contractors must keep and submit certified payroll records, and overtime on public works is owed after 8 hours a day and 40 hours a week.',
    points: ['Underpayment penalty up to $200 per worker per calendar day (floors of $40, $80 with prior penalties within 3 years, $120 if willful) plus the wage differential (§ 1775 — amended by SB 909 (2026); verify current figures).', 'Public-works overtime: 1.5× after 8/day and 40/week (§ 1815); $25 per worker per day for excess hours (§ 1813). Projects of $1,000 or less are exempt (§ 1771).', 'Penalty of $25 per worker per day for overtime violations on public works (Lab. Code § 1813).', 'Contractors and subcontractors must register with DIR before bidding.'],
    citations: ['Lab. Code § 1775', 'Lab. Code §§ 1720, 1771, 1774, 1776, 1813, 1815', 'Lab. Code § 1725.5'], keywords: ['public works', 'prevailing wage', 'certified payroll', 'government contract', 'dir registration'] },
  { id: 'la-hotel-wage', title: 'Los Angeles hotel worker minimum wage', verified: V, category: 'Minimum wage',
    summary: 'Hotels in the City of Los Angeles with more than 60 guest rooms must pay hotel workers $22.50 per hour from July 1, 2025 and $25.00 from July 1, 2026, plus a $4.25 hourly health benefit payment from July 1, 2026, under the ordinance as amended effective June 29, 2026.',
    points: ['Scheduled rates: $25.50 (July 1, 2027), $28.50 (July 1, 2028), $29.00 (July 1, 2029), $30.00 (January 1, 2030).', 'The health benefit rises to $6.00 per hour on July 1, 2027.', 'Related airport worker wage provisions apply under the City’s Living Wage Ordinance.'],
    citations: ['L.A. Mun. Code, ch. XVIII, art. 6 (Citywide Hotel Worker Minimum Wage Ordinance, as amended eff. June 29, 2026)', 'L.A. Mun. Code § 186.00 et seq. (Hotel Worker Minimum Wage Ordinance)', 'Los Angeles Office of Wage Standards'], keywords: ['hotel worker', 'olympic wage', 'los angeles hotel', 'hotel minimum wage', 'lax', 'airport workers'] },
  { id: 'recordkeeping', title: 'What time records must show', verified: V, category: 'Pay records and notices', engineRule: 'CA-RECORDS',
    summary: 'Employers must keep time records showing when each employee begins and ends each work period, and meal periods (except authorized meal periods during which operations cease), along with split-shift intervals and total daily hours. Records must be kept at least three years.',
    points: ['Missing meal records leave the employer unable to rebut meal-period claims and can support civil penalties.', 'Willful failure to keep required records carries a $500 civil penalty (Lab. Code § 1174.5).', 'Many point-of-sale time clocks don’t capture breaks unless configured to.'],
    citations: ['IWC Wage Orders § 7(A)', 'Lab. Code §§ 1174(d), 1174.5', 'Donohue v. AMN Services, LLC (2021) 11 Cal.5th 58'], keywords: ['records', 'recordkeeping', 'time records', 'meal punches', 'pos', 'time clock', 'record meal', 'doesnt record', 'doesn’t record', 'does not record', 'not recorded', 'record lunch', 'record breaks', 'no meal punches'] },
  { id: 'harassment-prevention', title: 'Harassment prevention policy and training', verified: V, category: 'Policies and leave',
    summary: 'Employers must take all reasonable steps to prevent harassment, discrimination, and retaliation, including a written policy with a complaint procedure, and employers with 5 or more employees must train supervisors (2 hours) and nonsupervisory employees (1 hour) every two years.',
    points: ['The written policy must list protected categories, allow complaints to someone other than a direct supervisor, and promise a prompt, fair investigation and no retaliation (Cal. Code Regs., tit. 2, § 11023).', 'Harassment protections apply to employers of any size.'],
    citations: ['Gov. Code §§ 12940(j)–(k), 12950.1', 'Cal. Code Regs., tit. 2, § 11023'], keywords: ['harassment', 'harassment training', 'anti-harassment policy', 'discrimination policy', '12950.1'] },
  { id: 'leaves', title: 'Family, pregnancy, bereavement, and reproductive loss leave', verified: V, category: 'Policies and leave',
    summary: 'Employers with 5 or more employees must provide: up to 12 weeks of CFRA leave to eligible employees; up to four months of pregnancy disability leave; up to five days of bereavement leave; and up to five days of reproductive loss leave per event (up to 20 days in 12 months).',
    points: ['CFRA eligibility: 12 months of service and 1,250 hours in the prior 12 months.', 'Bereavement and reproductive loss leave require 30 days of employment and must be taken within three months of the event.', 'Leave may be unpaid unless a policy provides pay; employees may use accrued paid time.'],
    citations: ['Gov. Code § 12945.2 (CFRA)', 'Gov. Code § 12945 (PDL)', 'Gov. Code § 12945.7 (bereavement)', 'Gov. Code § 12945.6 (reproductive loss)'], keywords: ['cfra', 'family leave', 'pregnancy leave', 'bereavement', 'reproductive loss', 'miscarriage leave', 'pdl', 'leave policy'] },
  { id: 'workplace-violence', title: 'Workplace violence prevention plans (SB 553)', verified: V, category: 'Policies and leave',
    summary: 'Since July 1, 2024, most California employers must maintain a written workplace violence prevention plan, train employees annually, keep a violent incident log, and retain records.',
    points: ['Exemptions include certain health care facilities covered by other standards, remote workers, and small workplaces not accessible to the public with fewer than 10 employees present.'],
    citations: ['Lab. Code § 6401.9 (SB 553, 2023)'], keywords: ['workplace violence', 'sb 553', 'violence prevention plan', 'incident log'] },
  { id: 'cannabis', title: 'Off-duty cannabis use', verified: V, category: 'Policies and leave',
    summary: 'Since January 1, 2024, employers with 5 or more employees may not discriminate based on a person’s off-duty, off-site cannabis use or on drug tests that detect only non-psychoactive cannabis metabolites, and may not ask applicants about prior cannabis use.',
    points: ['Employers may still prohibit possession, impairment, and use at work.', 'Exceptions include building and construction trades and positions requiring federal background checks or clearances.'],
    citations: ['Gov. Code § 12954 (AB 2188, 2022; SB 700, 2023)'], keywords: ['cannabis', 'marijuana', 'drug test', 'ab 2188', 'thc'] },
  { id: 'non-competes', title: 'Non-compete agreements are void', verified: V, category: 'Agreements and settlements',
    summary: 'Contracts that restrain anyone from engaging in a lawful profession, trade, or business are void in California regardless of where they were signed, and employers may not enter into or attempt to enforce them. Employers had to notify affected current and former employees by February 14, 2024 that such clauses were void.',
    points: ['Using a void non-compete is an act of unfair competition and gives employees a private right of action, including attorney’s fees.', 'Limited exceptions apply to the sale of a business or dissolution of a partnership.'],
    citations: ['Bus. & Prof. Code §§ 16600, 16600.1, 16600.5', 'Edwards v. Arthur Andersen LLP (2008) 44 Cal.4th 937'], keywords: ['non-compete', 'noncompete', 'restrictive covenant', '16600', 'non-solicit'] },
  { id: 'separation-agreements', title: 'What a California separation agreement must include', verified: V, category: 'Agreements and settlements',
    summary: 'An agreement related to an employee’s separation must notify the employee of the right to consult an attorney and give at least five business days to do so; any non-disparagement or confidentiality clause must include the statutory carve-out for disclosing unlawful acts; and releases of age claims must satisfy the federal Older Workers Benefit Protection Act.',
    points: ['Required carve-out (in substantial form): “Nothing in this agreement prevents you from discussing or disclosing information about unlawful acts in the workplace, such as harassment or discrimination or any other conduct that you have reason to believe is unlawful.”', 'Age claims: written advice to consult an attorney, 21 days to consider (45 for group programs), and 7 days to revoke.', 'No-rehire clauses are generally prohibited in agreements resolving employment disputes (Code Civ. Proc. § 1002.5).', 'Agreements may not restrict disclosure of factual information about filed claims of sexual assault, sexual harassment, or sex-based harassment, discrimination, or retaliation (Code Civ. Proc. § 1001).', 'Wages concededly due cannot be conditioned on a release (Lab. Code § 206.5); a general release should waive Civil Code § 1542.'],
    citations: ['Gov. Code § 12964.5', 'Code Civ. Proc. §§ 1001, 1002.5', '29 U.S.C. § 626(f)', 'Civ. Code § 1542', 'Lab. Code § 206.5'], keywords: ['separation agreement', 'severance', 'release', 'five business days', '12964.5', 'owbpa', 'severance agreement', 'non-disparagement'] },
  { id: 'class-settlements', title: 'Approval and valuation of class and PAGA settlements', verified: V, category: 'Agreements and settlements',
    summary: 'Courts approving a class settlement must make an informed evaluation of the strength of the claims against the amount offered, which requires an understanding of the amount in controversy and the realistic range of outcomes — typically a claim-by-claim estimate of the maximum realistic recovery, workweeks, and per-member payments.',
    points: ['Approved wage-and-hour settlements commonly fall around 10–35% of realistic exposure; for example, a Santa Barbara Superior Court final approval found a settlement of about 25% of realistic liability reasonable (Case No. 22CV00951).', 'Attorney’s fees are commonly awarded as a percentage of the common fund (often one-third), subject to a lodestar cross-check.', 'PAGA settlements must be submitted to the LWDA and approved by the court; for notices on or after June 19, 2024, penalties are split 65% LWDA / 35% employees.', 'Courts scrutinize the wage vs. penalty tax allocation and the release scope.'],
    citations: ['Kullar v. Foot Locker Retail, Inc. (2008) 168 Cal.App.4th 116', 'Laffitte v. Robert Half International Inc. (2016) 1 Cal.5th 480', 'Lab. Code § 2699(s)', 'Cal. Rules of Court, rule 3.769'], keywords: ['class settlement', 'settlement approval', 'kullar', 'preliminary approval', 'common fund', 'starting demand', 'case value', 'mediation'] },
  { id: 'new-laws-2027', title: 'New California employment laws for 2027', verified: V, category: 'Recent changes',
    summary: 'Effective January 1, 2027 (unless noted): the state minimum wage rises to $17.40 per hour, raising the exempt salary floor to $72,384; H-2A agricultural employers must pay $19.75 per hour to H-2A workers and to “corresponding” employees doing the same or substantially similar work for the same employer in the same county, adjusted annually by the Social Security COLA (Lab. Code § 1208, AB 2646); and employers must finish bringing existing “stay-or-pay” agreements into compliance with AB 692 (AB 1697).',
    points: ['Pay data reports expand from 10 job categories to the 23 Standard Occupational Classification major groups (SB 464).', 'Workplace surveillance: no tools that infer emotional state or collect neural data (AB 1883); no monitoring in workplace bathrooms (AB 1331).', 'Labor Code section 1019’s list of unfair immigration-related practices is broadened.', 'More than 30 cities and counties change their rates on January 1, 2027; cities announce the new figures late in the year. Where a local rate is below $17.40 (for example Oakland, $17.34), the state rate applies.', 'No new wage-and-hour or PAGA procedure bills were enacted in 2026.'],
    citations: ['Lab. Code § 1182.12', 'Lab. Code § 1208 (AB 2646, 2026)', 'AB 1697 (2026); AB 692 (2025)', 'SB 464 (2025)', 'AB 1883 (2026)', 'AB 1331 (2026)', 'Lab. Code § 1019'], keywords: ['2027', 'new laws', 'minimum wage 2027', '17.40', 'stay or pay', 'ab 692', 'trap', 'pay data', 'surveillance', 'ab 2646', 'agricultural minimum wage', 'next year'] },
  { id: 'seating', title: 'Suitable seating', verified: V, category: 'Hours and pay',
    summary: 'When the nature of the work reasonably permits sitting, employers must provide suitable seats; when employees are not engaged in active duties and the work requires standing, seats must be placed nearby. The analysis looks at tasks performed at a location, not the whole job.',
    points: ['A frequent PAGA allegation for cashiers, front-desk, and security positions.', 'An employer’s preference for standing is only one factor; the feasibility of the tasks while seated controls.'],
    citations: ['IWC Wage Orders § 14', 'Kilby v. CVS Pharmacy, Inc. (2016) 63 Cal.4th 1'], keywords: ['seating', 'seat', 'stool', 'stand', 'standing', 'cashier sit', 'kilby'] },
  { id: 'on-duty-meal', title: 'On-duty meal periods', verified: V, category: 'Breaks',
    summary: 'An on-duty meal period is allowed only when the nature of the work prevents relief from all duty and the employer and employee agree in writing; the agreement must state that the employee may revoke it in writing at any time, and the on-duty meal is paid time.',
    points: ['“Nature of the work” is narrow — e.g., a sole worker who cannot close the location; convenience or staffing shortfalls do not qualify.', 'Without both conditions, the meal is not compliant and a premium is owed.'],
    citations: ['IWC Wage Orders § 11(A) (§ 11(C) in some orders)', 'Lab. Code § 512', 'Brinker (2012) 53 Cal.4th 1004'], keywords: ['on-duty meal', 'on duty meal', 'eat while working', 'sole employee', 'nature of the work'] },
  { id: 'alternative-workweek', title: 'Alternative workweek schedules', verified: V, category: 'Hours and pay',
    summary: 'Employers may adopt a regularly scheduled alternative workweek of up to 10 hours per day within a 40-hour week without daily overtime, but only after a secret-ballot election approved by at least two-thirds of the affected work unit, following written disclosure at least 14 days before the vote; results must be reported to the Division of Labor Statistics and Research within 30 days.',
    points: ['Overtime is still owed for hours beyond the scheduled day (and over 40 per week), and double time after 12 hours.', 'Invalid elections mean ordinary daily overtime was owed all along — a common class claim.'],
    citations: ['Lab. Code §§ 511, 510', 'IWC Wage Orders § 3(B)–(C)'], keywords: ['alternative workweek', '4/10', 'four tens', '9/80', 'aws', 'compressed schedule', 'secret ballot'] },
  { id: 'computer-professionals', title: 'Computer professional exemption', verified: V, category: 'Classification',
    summary: 'Computer software employees can be exempt from overtime if they meet the duties test and are paid at least the annually adjusted rate — $58.85 per hour or $122,573.13 per year for 2026.',
    points: ['Duties must be primarily intellectual or creative and involve independent judgment in systems analysis, design, or programming.', 'Trainees, help-desk staff, and employees who only use software do not qualify.'],
    citations: ['Lab. Code § 515.5'], keywords: ['computer professional', 'software engineer exempt', 'programmer overtime', '515.5', 'it exempt'] },
  { id: 'minors', title: 'Minors: work permits and hours', verified: V, category: 'Policies and leave',
    summary: 'Minors under 18 generally need a work permit issued through their school. Ages 16–17: up to 4 hours on a school day (8 on a day before a non-school day), 8 hours on a non-school day, and 48 hours per week. Ages 14–15: up to 3 hours on a school day, 8 on a non-school day, 18 hours in a school week, and 40 in a non-school week.',
    points: ['Hazardous occupations are prohibited, and late-night limits apply by age.', 'Keep work permits on file; violations carry civil penalties.'],
    citations: ['Lab. Code §§ 1285–1312, 1391–1394', 'Ed. Code § 49110 et seq.'], keywords: ['minor', 'minors', 'teen', 'teenager', 'work permit', 'child labor', 'under 18', '16 year old', '15 year old'] },
  { id: 'cal-warn', title: 'Cal-WARN: layoffs, relocations, and closures', verified: V, category: 'Separation',
    summary: 'Employers of 75 or more employees in the prior 12 months must give 60 days’ written notice before a mass layoff (50 or more employees within 30 days), relocation, or termination at a covered establishment — to affected employees, the EDD, the local workforce board, and local officials.',
    points: ['Covered employees must have worked at least 6 of the prior 12 months; “relocation” means moving substantially all operations 100 or more miles.', 'Back pay is owed at the higher of the employee’s 3-year average or final rate, plus benefit value, for the lesser of 60 days or half the days employed (§ 1402); the $500-per-day penalty is excused if all § 1402 amounts are paid within three weeks (§ 1403).', '§§ 1400.5 and 1401 were amended by SB 951 / SB 617 effective January 1, 2026 — verify current notice content.', 'Violations: back pay and benefits for up to 60 days per employee, plus a civil penalty of up to $500 per day.', 'Unlike the federal WARN Act, Cal-WARN has no percentage threshold for layoffs.'],
    citations: ['Lab. Code §§ 1400–1408'], keywords: ['warn', 'cal-warn', 'layoff', 'layoffs', 'laying off', 'lay off', 'laid off', 'mass layoff', 'plant closure', 'closing a location', 'shut down', 'relocation', 'reduction in force', 'rif', 'furlough'] },
  { id: 'background-checks', title: 'Background checks and hiring', verified: V, category: 'Policies and leave',
    summary: 'Employers with five or more employees may not ask about conviction history before a conditional offer; afterward they must make an individualized assessment, give written notice of a preliminary decision with the report, allow at least five business days to respond, and give a final written notice. Credit reports are limited to specified positions, and salary-history questions are prohibited.',
    points: ['Consumer reports require stand-alone disclosures and consent.', 'Arrests not resulting in conviction and sealed or dismissed records generally may not be considered.'],
    citations: ['Gov. Code § 12952', 'Cal. Code Regs., tit. 2, § 11017.1', 'Lab. Code §§ 432.3, 432.7, 1024.5', 'Civ. Code § 1786 et seq.'], keywords: ['background check', 'ban the box', 'fair chance', 'criminal history', 'conviction', 'credit check', 'salary history', 'hiring'] },
  { id: 'time-off-rights', title: 'Other protected time off', verified: V, category: 'Policies and leave',
    summary: 'California protects time off for jury and witness duty, voting (up to 2 hours paid when needed), school and child-care activities (employers with 25+: up to 40 hours per year, 8 per month), organ and bone marrow donation (paid leave at 15+ employees), volunteer emergency service, and military-spouse leave (25+ employees, up to 10 days).',
    points: ['Retaliation for taking protected leave is prohibited.', 'Employers may require reasonable notice and documentation where the statute allows.'],
    citations: ['Lab. Code §§ 230, 230.3, 230.8, 1510–1513', 'Elec. Code § 14000', 'Mil. & Vet. Code § 395.10'], keywords: ['jury duty', 'voting', 'vote', 'school activities', 'organ donor', 'bone marrow', 'volunteer firefighter', 'military spouse', 'time off'] },
  { id: 'pfl-sdi', title: 'Paid Family Leave and State Disability Insurance', verified: V, category: 'Policies and leave',
    summary: 'PFL and SDI are wage-replacement benefits paid by the EDD from employee contributions; they do not themselves protect the job. Job protection comes from CFRA (5+ employees, up to 12 weeks) and pregnancy disability leave (up to 4 months). Since 2025, benefit rates are 70% to 90% of wages depending on income.',
    points: ['Give the DE 2511 (PFL) and DE 2515 (SDI) brochures at hire and when leave begins.', 'Since 2018, employers may not require employees to use vacation before receiving PFL benefits (AB 908).'],
    citations: ['Unemp. Ins. Code §§ 2601 et seq., 3300 et seq.', 'Gov. Code §§ 12945, 12945.2', 'SB 951 (2022)'], keywords: ['paid family leave', 'pfl', 'sdi', 'disability insurance', 'edd', 'baby bonding', 'family leave pay'] },
  { id: 'payment-methods', title: 'How wages may be paid', verified: V, category: 'Hours and pay',
    summary: 'Paychecks must be negotiable and payable in cash on demand, without discount, at an established California bank; direct deposit requires the employee’s voluntary written authorization. Pay cards must allow fee-free access to the full wages.',
    points: ['Scrip, coupons, or IOUs are prohibited.', 'Bounced paychecks can trigger penalties of up to 30 days’ wages.'],
    citations: ['Lab. Code §§ 203.1, 212, 213'], keywords: ['direct deposit', 'pay card', 'paycard', 'paycheck', 'check cashing', 'how to pay wages', 'bounced check'] },
  { id: 'pay-data-reporting', title: 'Pay data reporting', verified: V, category: 'Pay records and notices',
    summary: 'Private employers with 100 or more employees (and those with 100 or more workers hired through labor contractors) must file an annual pay data report with the Civil Rights Department by the second Wednesday of May, including median and mean hourly rates by job category, race, ethnicity, and sex. From 2027, reports use 23 occupational groups instead of 10.',
    points: ['Penalties up to $100 per employee for a first failure and $200 per employee for later failures.', 'Pay data analysis is also a strong defense tool for equal-pay claims.'],
    citations: ['Gov. Code § 12999', 'SB 464 (2025)'], keywords: ['pay data', 'pay data report', '12999', 'crd report', 'eeo pay'] },
  { id: 'workers-comp', title: 'Workers’ compensation duties', verified: V, category: 'Policies and leave',
    summary: 'Every employer must carry workers’ compensation insurance (or be certified to self-insure), give the new-hire pamphlet, post the notice to employees, and provide a claim form (DWC-1) within one working day after learning of a work injury.',
    points: ['Operating uninsured is a crime and triggers stop orders and penalties.', 'Retaliating against injured workers is prohibited (Lab. Code § 132a).'],
    citations: ['Lab. Code §§ 132a, 3550, 3551, 3700, 5401'], keywords: ['workers comp', 'workers compensation', 'work injury', 'dwc-1', 'claim form', 'injured at work'] },
  { id: 'immigration-protections', title: 'Immigration-related protections', verified: V, category: 'Policies and leave',
    summary: 'Employers may not engage in unfair immigration-related practices — such as demanding more or different documents than the I-9 requires, misusing E-Verify, or threatening to report immigration status — in retaliation for protected activity. Employers must notify employees within 72 hours of receiving notice of an I-9 inspection.',
    points: ['Section 1019 was broadened for 2027.', 'Using E-Verify to check existing employees or applicants before an offer is restricted.'],
    citations: ['Lab. Code §§ 90.2, 1019, 1019.1, 2814'], keywords: ['immigration', 'i-9', 'e-verify', 'document abuse', 'ice', 'work authorization'] },
  { id: 'stay-or-pay', title: 'Stay-or-pay and training repayment agreements', verified: V, category: 'Agreements and settlements',
    summary: 'California restricts contract terms that require a worker to repay the employer — for training, bonuses, or other costs — if employment ends, subject to limited exceptions such as properly structured repayment for transferable credentials or discretionary sign-on bonuses. Existing agreements must comply by January 1, 2027.',
    points: ['Review sign-on bonus, relocation, and tuition agreements before 2027.', 'Workers have a private right of action.'],
    citations: ['AB 692 (2025)', 'AB 1697 (2026)'], keywords: ['stay or pay', 'training repayment', 'trap', 'repay bonus', 'clawback', 'tuition repayment', 'ab 692'] },
  { id: 'iipp-safety', title: 'Injury and Illness Prevention Program', verified: V, category: 'Policies and leave',
    summary: 'Every California employer must have a written Injury and Illness Prevention Program covering responsibility, hazard assessment, correction, training, communication, and recordkeeping, plus heat-illness procedures for outdoor (and, since 2024, many indoor) workplaces.',
    points: ['Workplace violence prevention plans became mandatory in 2024.', 'Cal/OSHA citations often accompany wage-and-hour investigations.'],
    citations: ['Lab. Code § 6401.7', 'Cal. Code Regs., tit. 8, §§ 3203, 3395, 3396'], keywords: ['iipp', 'injury and illness', 'cal/osha', 'safety program', 'indoor heat', 'heat illness plan'] },
  { id: 'paga-manageability', title: 'PAGA manageability and representative claims', verified: V, category: 'PAGA and enforcement',
    summary: 'Trial courts lack inherent authority to strike PAGA claims on manageability grounds, though they may limit evidence and the issues to be tried. An employee compelled to arbitrate individual claims keeps standing to pursue non-individual PAGA claims in court.',
    points: ['Defense strategy shifts to the merits, the 2024 penalty caps, and limiting the scope of “aggrieved employees.”'],
    citations: ['Estrada v. Royalty Carpet Mills (2024) 15 Cal.5th 582', 'Adolph v. Uber Technologies (2023) 14 Cal.5th 1104', 'Lab. Code § 2699'], keywords: ['manageability', 'strike paga', 'estrada', 'representative claim', 'non-individual paga'] },
  { id: 'meal-premium-timing', title: 'Meal and rest premiums: rate, timing, and reporting', verified: V, category: 'Breaks',
    summary: 'Premiums must be paid at the regular rate of compensation (including nondiscretionary pay), on the payday for the period in which the violation occurred, and listed on the wage statement. Unpaid premiums support wage-statement and waiting-time penalties.',
    points: ['One premium per day for meal violations and one per day for rest violations (two maximum per day).', 'Recovery-period (heat) premiums are separate.'],
    citations: ['Lab. Code § 226.7', 'Ferra v. Loews Hollywood Hotel (2021) 11 Cal.5th 858', 'Naranjo v. Spectrum Security Services (2022) 13 Cal.5th 93'], keywords: ['premium timing', 'when pay premium', 'premium rate', 'premium on paystub', 'how many premiums per day'] },
  { id: 'paga-penalty-tiers', title: 'PAGA penalty tiers, caps, cure, and anti-stacking (2024 reform)', verified: V, category: 'PAGA and enforcement',
    summary: 'For notices on or after June 19, 2024, the default PAGA penalty is $100 per aggrieved employee per pay period; $25 for most wage-statement violations where the employee could promptly and easily determine the correct information; $50 for an isolated, nonrecurring violation lasting no longer than the lesser of 30 consecutive days or four consecutive pay periods; $200 where the practice was found unlawful within the prior five years or the conduct was malicious, fraudulent, or oppressive; and $500 where the person employs no employees.',
    points: ['Weekly payroll: penalties are halved (§ 2699(o)).', 'Caps: 15% if all reasonable steps were taken before the notice or records request; 30% if taken within 60 days after the notice — but the caps do not apply to the $200 heightened penalty.', 'Cure: an employer that qualifies for a cap and cures owes no penalty; any other employer that cures owes at most $15 per employee per pay period.', 'Anti-stacking (§ 2699(i)): no separate PAGA penalty for §§ 201–203, non-willful § 204, or non-knowing § 226 violations on top of the penalty for the underlying unpaid-wage violation; courts may also reduce penalties where the same conduct caused multiple violations.', 'Courts may award less than, or more than, the statutory amount where the result would otherwise be unjust, arbitrary and oppressive, or confiscatory.', 'Allocation: 65% to the LWDA, 35% to aggrieved employees (75/25 for notices before June 19, 2024).', 'PAGA plaintiffs cannot recover underpaid wages through § 558 (Dole Food).'],
    citations: ['Lab. Code § 2699(f)–(o)', 'Dole Food Co. v. Superior Court (2015) 242 Cal.App.4th 894'], keywords: ['paga tiers', '$25 paga', '$50 paga', '$200 paga', 'heightened penalty', 'anti-stacking', 'stacking', '2699(i)', 'cure $15', 'reasonable steps cap', 'paga allocation'] },
  { id: 'paga-procedure', title: 'PAGA notice, exhaustion, cure, and early evaluation', verified: V, category: 'PAGA and enforcement',
    summary: 'Before suing, the employee must file a notice online with the LWDA and send it by certified mail to the employer, stating the specific Labor Code provisions and the facts and theories supporting each; exhaustion is a prerequisite. The employee may file suit after 65 days (120 if the LWDA investigates). Employers with fewer than 100 employees may submit a confidential cure proposal within 33 days; employers with 100 or more served with a complaint may request an early evaluation conference and stay.',
    points: ['Violations listed in § 2699.5 (including §§ 201–203) are not curable pre-suit.', 'A valid cure abates the violation, brings the employer into compliance, and makes employees whole — for wage claims, three years of unpaid wages plus 7% interest, any liquidated damages, and reasonable lodestar fees.', 'An employer may not cure the same violation more than once in 12 months.', 'Early evaluation: absent good cause the court stays the action and sets the conference within 70 days; the parties exchange confidential statements, including the plaintiff’s per-violation penalty calculation.', 'One-year limitations period; the pre-filing waiting periods do not count against it.'],
    citations: ['Lab. Code §§ 2699.3, 2699.5'], keywords: ['paga notice', 'lwda notice', 'exhaustion', '65 days', 'cure proposal', 'early evaluation', 'eec', '33 days', 'paga procedure'] },
  { id: 'paga-standing', title: 'PAGA standing and arbitration', verified: V, category: 'PAGA and enforcement',
    summary: 'An “aggrieved employee” is a person employed by the alleged violator who personally suffered each alleged violation within the one-year period. Settling individual claims does not end standing to pursue representative PAGA claims (Kim). Where an arbitration agreement applies, the individual PAGA claim is compelled to arbitration (Viking River), but the plaintiff keeps standing for non-individual claims, which may be stayed (Adolph).',
    points: ['Individual settlement programs reduce class claims but do not release the State’s representative PAGA claims.', 'Draft arbitration agreements with PAGA severability in mind.'],
    citations: ['Lab. Code § 2699(c)', 'Kim v. Reins International California, Inc. (2020) 9 Cal.5th 73', 'Viking River Cruises, Inc. v. Moriana (2022) 596 U.S. 639', 'Adolph v. Uber Technologies, Inc. (2023) 14 Cal.5th 1104'], keywords: ['paga standing', 'aggrieved employee', 'personally suffered', 'kim v reins', 'viking river', 'individual paga claim'] },
  { id: 'min-wage-penalties', title: 'Minimum wage: civil penalties and liquidated damages', verified: V, category: 'Minimum wage',
    summary: 'An employer that pays less than minimum wage owes the unpaid wages, liquidated damages equal to the unpaid wages plus interest, and a civil penalty of $100 per underpaid employee per pay period for an initial intentional violation and $250 for each subsequent violation, plus any waiting-time penalties.',
    points: ['Liquidated damages are available only for minimum-wage violations — never for unpaid overtime.', 'Liquidated damages may be reduced or denied if the employer shows good faith and reasonable grounds.'],
    citations: ['Lab. Code §§ 1194, 1194.2, 1197.1'], keywords: ['liquidated damages', '1194.2', '1197.1', 'minimum wage penalty', 'double damages'] },
  { id: 'late-pay-penalties', title: 'Late payment of wages during employment', verified: V, category: 'Hours and pay',
    summary: 'Wages are due at least twice a month on designated paydays: work from the 1st–15th by the 26th, and from the 16th–end of month by the 10th of the next month; paying weekly, biweekly, or semimonthly within 7 calendar days after the period closes satisfies § 204. Late payment carries a penalty of $100 per employee for an initial violation and $200 plus 25% of the amount withheld for subsequent or willful violations.',
    points: ['Overtime may be paid by the next regular payday.', 'An employee may recover either the § 210 penalty or a PAGA penalty for the same violation, not both.'],
    citations: ['Lab. Code §§ 204, 210'], keywords: ['late paycheck', 'late pay', 'paid late', '210 penalty', 'payday timing', 'semimonthly'] },
  { id: 'labor-commissioner-penalties', title: 'Labor Commissioner citations: wage statements and records', verified: V, category: 'Pay records and notices',
    summary: 'The Labor Commissioner may cite employers $250 per employee per violation (initial) and $1,000 per employee per violation (subsequent) for failing to provide compliant wage statements or keep required records, and $500 for willfully failing to maintain records or allow inspection.',
    points: ['A first violation that was inadvertent or clerical may be excused.', 'Separately, employees may recover § 226(e) penalties of $50 / $100 per pay period, up to $4,000, for knowing and intentional failures; injury is deemed when the employee cannot promptly and easily determine required information from the statement alone.'],
    citations: ['Lab. Code §§ 226(e), 226.3, 1174, 1174.5'], keywords: ['226.3', '1174.5', 'labor commissioner citation', 'records penalty', 'wage statement penalty'] },
  { id: 'meal-cba-exemptions', title: 'Meal-period CBA exemptions and security officers', verified: V, category: 'Breaks',
    summary: 'Section 512’s meal-period rules do not apply to employees in construction, commercial driving, registered security services, and certain utility work who are covered by a valid collective bargaining agreement that expressly provides for meal periods, final and binding arbitration of meal-period disputes, premium wages for overtime, and a regular hourly rate at least 30% above the state minimum wage.',
    points: ['Check for a qualifying CBA before flagging meal violations in these industries.', 'CBA-covered registered security officers may be required to remain on call during rest periods; if an uninterrupted 10-minute rest is not permitted, the officer receives one additional hour at the regular base hourly rate.'],
    citations: ['Lab. Code §§ 512(e)–(f), 226.7'], keywords: ['cba exemption', 'collective bargaining meal', 'security officer rest', 'construction meal exemption', 'union meal'] },
  { id: 'settlement-approval', title: 'Class settlement approval and release scope', verified: V, category: 'Agreements and settlements',
    summary: 'Courts must find a class settlement fair, reasonable, and adequate, considering the Dunk factors — strength of the case; risk, expense, complexity, and duration of further litigation; risk of maintaining class status; amount offered; extent of discovery; experience and views of counsel; presence of a governmental participant; and class members’ reaction. A presumption of fairness arises from arm’s-length bargaining, sufficient investigation, experienced counsel, and few objectors, but it fails without real investigation of each claim (Kullar).',
    points: ['Releases may cover claims that could have been alleged only if based on the identical factual predicate; releases of claims “in any way relating” to the complaint are overbroad (Amaro).', 'A wage-and-hour release does not reach distinct claims such as § 1102.5 retaliation based on a different factual predicate.', 'PAGA settlements require court approval and simultaneous submission to the LWDA; courts may refuse unfair PAGA releases.'],
    citations: ['Dunk v. Ford Motor Co. (1996) 48 Cal.App.4th 1794', 'Kullar v. Foot Locker Retail, Inc. (2008) 168 Cal.App.4th 116', 'Amaro v. Anaheim Arena Management, LLC (2021) 69 Cal.App.5th 521', 'Lab. Code § 2699(s)'], keywords: ['dunk factors', 'fair reasonable adequate', 'release scope', 'identical factual predicate', 'amaro', 'preliminary approval', 'settlement approval'] },
  { id: 'sampling-duran', title: 'Statistical sampling and damages models', verified: V, category: 'PAGA and enforcement',
    summary: 'Sampling may support class-wide damages, but a sampling plan must be developed with expert input, must let the defendant impeach the model or show reduced liability, and the trial plan must allow litigation of relevant affirmative defenses even when they turn on individual questions. Duran reversed a judgment built on a small, non-random sample with a very large margin of error.',
    points: ['Best practice: analyze all time and payroll records, or a statistically valid random sample, with a statistician (Amaro).', 'Aldune analyzes every record you provide rather than sampling; disclose any extrapolation and its margin of error.'],
    citations: ['Duran v. U.S. Bank National Assn. (2014) 59 Cal.4th 1', 'Amaro v. Anaheim Arena Management, LLC (2021) 69 Cal.App.5th 521'], keywords: ['sampling', 'statistical sampling', 'extrapolation', 'margin of error', 'duran', 'expert damages'] },
  { id: 'law-watch-list', title: 'Law watch list: authorities to re-verify', verified: V, category: 'Recent changes',
    summary: 'Items that may change and require re-verification before relying on outputs: the version of Labor Code § 226.7 operative until January 1, 2027 (confirm the successor text); any amendments to § 2699 after the 2024 reform; Naranjo’s continued vitality (recently distinguished on one point); federal-preemption limits on § 246 sick leave in the railroad context; Camp v. Home Depot (rounding) pending in the California Supreme Court; and January 1, 2027 local minimum wages.',
    points: ['Pending or recent amendments to verify: § 1775 prevailing-wage penalties (SB 909, 2026); §§ 1400.5 and 1401 Cal-WARN (SB 951 / SB 617, effective Jan. 1, 2026); § 98.2 Berman appeals (SB 261); the § 1182.16 funding trigger for SB 525 health care rates; §§ 2778 and 2783 AB 5 exemptions (Jan. 1, 2026 texts).', 'Case-law monitoring: See’s Candy (negative treatment), Borello (overruling risk), Alvarado / Levanoff (regular-rate), Naranjo (distinguished), and Camp (review granted, no merits decision).', 'Aldune marks affected findings for attorney review when a watched authority changes.', 'Limitations note: Aldune uses three years for § 203 waiting-time penalties because § 203(b) ties the period to the underlying wage claim (Pineda v. Bank of America (2010) 50 Cal.4th 1389); some sources state one year — confirm with counsel.'],
    citations: ['Lab. Code §§ 203(b), 226.7, 246, 2699', 'Pineda v. Bank of America, N.A. (2010) 50 Cal.4th 1389', 'Naranjo v. Spectrum Security Services (2022) 13 Cal.5th 93'], keywords: ['watch list', 'what may change', 'verify', 'pending law', '226.7 2027', 'law changes'] },
  { id: 'off-the-clock', title: 'Off-the-clock work (no California de minimis rule)', verified: V, category: 'Hours and pay',
    summary: 'California has not adopted the federal de minimis doctrine: employers may not require employees to work off the clock for small amounts of time on a regular basis. Only truly irregular or brief activities may be excused; employers are expected to capture small increments through work restructuring, technology, or time studies.',
    points: ['Flag systematic gaps between the first or last work activity (badge-in, system login, security screening, closing duties) and clock time; recurring minutes are wages, not de minimis.', 'Liability requires that the employer knew or should have known of the work (Brinker); unpaid time cascades to wage-statement and waiting-time claims.'],
    citations: ['Troester v. Starbucks Corp. (2018) 5 Cal.5th 829', 'Brinker (2012) 53 Cal.4th 1004', 'Lab. Code §§ 1194, 1197'], keywords: ['off the clock', 'off-the-clock', 'de minimis', 'troester', 'closing duties', 'pre-shift', 'post-shift', 'security check', 'unpaid minutes'] },
  { id: 'equal-pay', title: 'California Equal Pay Act', verified: V, category: 'Hours and pay',
    summary: 'Employers may not pay employees of another sex, race, or ethnicity less for substantially similar work (a composite of skill, effort, and responsibility under similar conditions) unless the entire difference is explained by seniority, merit, a production-based system, or a bona fide job-related factor consistent with business necessity. Prior salary cannot justify a disparity.',
    points: ['Remedies: the wage differential plus an equal amount as liquidated damages, interest, costs, and fees.', 'Limitations: three years, with recovery reaching back up to six; retaliation claims have a one-year period and a 90-day presumption.', 'Aldune surfaces pay differences for attorney review; it never concludes liability from statistics alone.'],
    citations: ['Lab. Code § 1197.5'], keywords: ['equal pay', 'pay equity', 'gender pay gap', 'same work less pay', '1197.5', 'pay discrimination'] },
  { id: 'minimum-wage-indexing', title: 'How the state minimum wage is set each year', verified: V, category: 'Minimum wage',
    summary: 'After reaching $15 (2022 for 26+ employees, 2023 for smaller employers), the state minimum wage is adjusted each January 1 by the lesser of 3.5% or the change in the U.S. CPI-W, rounded to the nearest $0.10, never decreasing; the Director of Finance announces it by August 1. Local ordinances may set higher rates, and the highest applicable rate controls.',
    points: ['2026: $16.90; 2027: $17.40 (announced July 2026).', 'Exempt salary floor = 2 × state minimum wage × 2,080 hours ($72,384 in 2027).'],
    citations: ['Lab. Code §§ 1182.12, 1197'], keywords: ['minimum wage increase', 'cpi', 'how is minimum wage set', 'indexing', 'next minimum wage', '1182.12'] },
  { id: 'physician-exemption', title: 'Licensed physician exemption', verified: V, category: 'Classification',
    summary: 'Licensed physicians and surgeons primarily performing duties requiring the license may be exempt from overtime if paid at least an annually CPI-adjusted hourly rate (statutory baseline $55.00). Interns, residents, and physicians covered by a collective bargaining agreement are excluded.',
    points: ['Store the indexed rate by year; the $55 figure is a baseline, not the current amount.'],
    citations: ['Lab. Code § 515.6'], keywords: ['physician exempt', 'doctor overtime', '515.6', 'surgeon exemption'] },
  { id: 'kin-care', title: 'Kin care', verified: V, category: 'Policies and leave',
    summary: 'An employer that provides sick leave must let employees use, each calendar year, accrued sick leave up to the amount accrued in six months to care for family members, at the employee’s discretion. Denying or retaliating for kin-care use entitles the employee to reinstatement and actual damages or one day’s pay (whichever is greater), plus attorney’s fees.',
    points: ['Applies to the employer’s own sick leave plan, not just the statutory minimum.'],
    citations: ['Lab. Code § 233'], keywords: ['kin care', 'care for family member', 'sick leave for family', '233'] },
  { id: 'cfra', title: 'California Family Rights Act (CFRA)', verified: V, category: 'Policies and leave',
    summary: 'Employers with five or more employees must provide up to 12 workweeks of job-protected leave in a 12-month period to employees with more than 12 months of service and at least 1,250 hours in the prior 12 months — for bonding with a new child, caring for a family member (child, parent, grandparent, grandchild, sibling, spouse, domestic partner, or designated person) with a serious health condition, the employee’s own serious health condition, or a military exigency — with reinstatement to the same or a comparable position.',
    points: ['Interference and retaliation are FEHA violations.', 'Handbooks of 5+-employee employers need a compliant CFRA policy.'],
    citations: ['Gov. Code § 12945.2'], keywords: ['cfra', 'family leave', 'medical leave', '12 weeks leave', 'bonding leave', 'job protected leave'] },
  { id: 'classification-routing', title: 'Which worker-status test applies to which claim', verified: V, category: 'Classification',
    summary: 'The ABC test governs claims arising under the wage orders — minimum and unpaid wages, meal and rest periods, and wage statements — while Borello’s common-law test governs claims not arising under a wage order. The analysis is per claim, not per worker. If the hiring entity satisfies any statutory exemption in Labor Code sections 2776–2784, Borello governs.',
    points: ['Default is employee status; the hiring entity must prove each ABC prong.'],
    citations: ['Garcia v. Border Transportation Group, LLC (2018) 28 Cal.App.5th 558', 'Lab. Code §§ 2775, 2785'], keywords: ['which test', 'abc or borello', 'contractor test', 'classification routing', 'garcia border'] },
  { id: 'borello-test', title: 'The Borello test', verified: V, category: 'Classification',
    summary: 'Where the ABC test does not apply, worker status turns principally on the hiring entity’s right to control the manner and means of the work, together with secondary factors: a distinct occupation or business; whether the work is usually done under direction or by a specialist; required skill; who supplies tools and the workplace; length of the relationship; payment by time or by the job; whether the work is part of the principal’s regular business; and what the parties believe — weighed together, not mechanically.',
    points: ['Borello also considers opportunity for profit or loss, investment in equipment or helpers, special skill, permanence, and whether the service is integral to the business.', 'Aldune reports a risk score with the factor breakdown — never a binary “contractor OK.”'],
    citations: ['S. G. Borello & Sons, Inc. v. Department of Industrial Relations (1989) 48 Cal.3d 341'], keywords: ['borello', 'right to control', 'common law test', 'contractor factors'] },
  { id: 'ab5-exemptions', title: 'AB 5 / AB 2257 exemptions', verified: V, category: 'Classification',
    summary: 'Statutory exemptions route classification to Borello when every condition is met: business-to-business contracts (§ 2776), referral agencies for listed services (§ 2777), professional services meeting six factors and listed occupations (§ 2778), single-engagement events (§ 2779), music and recording occupations (§ 2780), construction subcontractors with a written subcontract, CSLB license, business license, and separate location (§ 2781), data aggregators (§ 2782), occupational exemptions such as licensed physicians, lawyers, architects, engineers, accountants, insurance licensees, and direct sales (§ 2783), and motor clubs (§ 2784).',
    points: ['Referral-agency exemption excludes high-hazard, janitorial, delivery, trucking, agricultural, retail, logging, in-home care, and non-minor construction services.', '§§ 2778 and 2783 were revised effective January 1, 2026 — verify current text.'],
    citations: ['Lab. Code §§ 2776–2785', 'People v. Uber Technologies, Inc. (2020) 56 Cal.App.5th 266'], keywords: ['ab5', 'ab 5', 'ab 2257', 'business to business', 'professional services exemption', 'referral agency', 'contractor exemption'] },
  { id: 'joint-employer', title: 'Joint employers and the definition of “employ”', verified: V, category: 'Classification',
    summary: 'For wage claims, “employ” has three alternative meanings from the wage orders: exercising control over wages, hours, or working conditions; suffering or permitting work; or engaging the worker under common law. Staffing agencies, franchisors, labor contractors, and PEOs are analyzed under these alternatives; the ABC test does not apply to joint-employer claims where the worker is already an admitted employee of a primary employer.',
    points: ['“Suffer or permit” liability rests on knowing of and failing to prevent the work.', 'Client employers also share liability for labor-contractor wage violations under § 2810.3.'],
    citations: ['Martinez v. Combs (2010) 49 Cal.4th 35', 'Henderson v. Equilon Enterprises, LLC (2019) 40 Cal.App.5th 1111', 'Lab. Code § 2810.3'], keywords: ['joint employer', 'staffing agency liability', 'franchisor liability', 'peo', 'martinez v combs', 'suffer or permit'] },
  { id: 'willful-misclassification', title: 'Willful misclassification penalties', verified: V, category: 'Classification',
    summary: 'Voluntarily and knowingly misclassifying an employee as an independent contractor — or charging a misclassified worker fees or deductions — carries civil penalties of $5,000 to $15,000 per violation, and $10,000 to $25,000 per violation for a pattern or practice, in addition to other penalties.',
    points: ['Aldune adds this line only when misclassification is likely and evidence suggests the conduct was voluntary and knowing.'],
    citations: ['Lab. Code § 226.8'], keywords: ['willful misclassification', '226.8', 'misclassified contractor penalty', '1099 penalty'] },
  { id: 'section-558', title: 'Section 558 civil penalties', verified: V, category: 'PAGA and enforcement',
    summary: 'For violations of the hours and wage-order provisions, § 558 imposes $50 per underpaid employee per pay period (initial) and $100 (subsequent), plus an amount sufficient to recover underpaid wages paid to the employee. In PAGA actions, plaintiffs recover the penalty component but not the underpaid wages (Dole Food).',
    points: ['PAGA recovers either the § 2699(f) default penalty or a section-specific civil penalty such as §§ 558 or 1197.1.'],
    citations: ['Lab. Code § 558', 'Dole Food Co. v. Superior Court (2015) 242 Cal.App.4th 894'], keywords: ['558', 'section 558', 'underpaid wages penalty', 'wage order penalty'] },
  { id: 'class-procedure', title: 'Class procedure: notice, fees, cy pres, CAFA', verified: V, category: 'Agreements and settlements',
    summary: 'California class settlements require notice in plain language describing the action, class definition, claims, the right to appear and opt out, the deadline and method, and the binding effect of judgment (Cal. Rules of Court, rules 3.766, 3.769). Fees may be a percentage of the common fund with a discretionary lodestar cross-check (Laffitte); federal courts use a 25% benchmark. Unclaimed funds go to cy pres recipients under Code of Civil Procedure section 384.',
    points: ['CAFA: federal jurisdiction where more than $5,000,000 is in controversy with minimal diversity, subject to home-state and local-controversy exceptions and a 100-member minimum; any defendant may remove without the one-year limit.', 'A PAGA settlement must be submitted to the LWDA when submitted to the court; a competing PAGA plaintiff cannot intervene in or vacate another’s settlement (Turrieta v. Lyft).'],
    citations: ['Code Civ. Proc. §§ 382, 384', 'Cal. Rules of Court, rules 3.766, 3.769', 'Laffitte v. Robert Half International Inc. (2016) 1 Cal.5th 480', '28 U.S.C. §§ 1332(d), 1453', 'Turrieta v. Lyft, Inc. (2024) 16 Cal.5th 664'], keywords: ['class notice', 'cy pres', 'unclaimed funds', 'cafa', 'removal', 'attorney fees percentage', 'turrieta', 'lodestar'] },
  { id: 'criminal-wage-exposure', title: 'Criminal exposure for wage violations', verified: V, category: 'PAGA and enforcement',
    summary: 'Willfully refusing to pay wages due with the ability to pay, or falsely denying wages to secure a discount or to harass or defraud, is a misdemeanor (§ 216). Intentional theft of more than $950 in wages from one employee, or $2,350 in the aggregate from two or more, within any consecutive 12 months may be prosecuted as grand theft, with restitution of wages (Pen. Code § 487m).',
    points: ['Aldune flags when unpaid amounts cross these thresholds so counsel can assess intent — it never treats them as a civil penalty.', '“Employee” in § 487m includes independent contractors.'],
    citations: ['Lab. Code § 216', 'Pen. Code § 487m'], keywords: ['wage theft crime', 'criminal', '487m', 'grand theft wages', '216', 'prosecution'] },
  { id: 'successor-liability', title: 'Successor liability for wage judgments', verified: V, category: 'PAGA and enforcement',
    summary: 'A successor to an employer with a final wage judgment is liable for those wages, damages, and penalties if it uses substantially the same facilities or workforce for substantially the same services, has substantially the same owners or managers controlling labor relations, employs a managing agent who controlled wages and hours, or is in the same industry with an owner or officer who is an immediate family member.',
    points: ['Use in M&A diligence: screen targets for unpaid wage judgments and these four criteria.'],
    citations: ['Lab. Code § 200.3'], keywords: ['successor liability', 'buying a business', 'asset purchase wages', 'm&a', 'acquisition wage judgment'] }
];

export interface LawHit { topic: LawTopic; score: number }
const STOP = new Set(['the', 'a', 'an', 'is', 'are', 'what', 'how', 'do', 'does', 'for', 'of', 'to', 'in', 'on', 'we', 'our', 'can', 'i', 'my', 'and', 'or', 'about', 'it', 'be', 'when', 'with', 'california', 'ca', 'law', 'rule', 'rules']);
export function searchLaw(q: string, limit = 3): LawHit[] {
  const ql = q.toLowerCase(); const terms = ql.split(/[^a-z0-9$.%']+/).filter(t => t && !STOP.has(t));
  return LAW.map(topic => {
    let score = 0;
    for (const k of topic.keywords) if (ql.includes(k)) score += k.includes(' ') ? 6 : 4;
    const hay = `${topic.title} ${topic.summary} ${topic.points.join(' ')}`.toLowerCase();
    for (const t of terms) if (t.length > 2 && hay.includes(t)) score += 1;
    const title = topic.title.toLowerCase(); for (const t of terms) if (t.length > 3 && title.includes(t)) score += 3;
    if (ql.includes(topic.title.toLowerCase())) score += 8;
    return { topic, score };
  }).filter(h => h.score >= 4).sort((a, b) => b.score - a.score).slice(0, limit);
}
export const lawById = (id: string) => LAW.find(t => t.id === id) || null;

export const LAW_CATEGORIES = ['Breaks', 'Hours and pay', 'Minimum wage', 'Classification', 'Pay records and notices', 'Separation', 'PAGA and enforcement', 'Agreements and settlements', 'Industries', 'Policies and leave', 'Recent changes'];
